48	 * Costo de una carga en casa: recorre minuto a minuto el rango [startAt, endAt) clasificando
49	 * cada minuto, y reparte los kWh totales proporcionalmente al tiempo pasado en cada franja
50	 * (asume tasa de carga constante — no hay forma de conocer la potencia instantánea real sin
51	 * monitoreo en vivo del cargador, que quedó fuera de alcance en Fase 12).
52	 */
53	export function computeHomeChargeCost(
54	  startAt: Date,
55	  endAt: Date,
56	  totalKwh: number,
57	  rates: TariffRates,
58	  puntaStartHour: number,
59	): ChargeBreakdown {
60	  const totalMinutes = Math.round((endAt.getTime() - startAt.getTime()) / 60000);
61	  if (totalMinutes <= 0) {
62	    throw new Error('La hora de fin debe ser posterior a la de inicio.');
63	  }
64	  if (totalKwh <= 0) {
65	    throw new Error('Los kWh cargados deben ser mayores a cero.');
66	  }
67	
68	  const minutesByClass: Record<RateClass, number> = { valle: 0, llano: 0, punta: 0 };
69	  const cursor = new Date(startAt);
70	  for (let m = 0; m < totalMinutes; m++) {
71	    minutesByClass[classifyHour(cursor, puntaStartHour)]++;
72	    cursor.setMinutes(cursor.getMinutes() + 1);
73	  }
74	
75	  const valleKwh = (minutesByClass.valle / totalMinutes) * totalKwh;
76	  const llanoKwh = (minutesByClass.llano / totalMinutes) * totalKwh;
77	  const puntaKwh = (minutesByClass.punta / totalMinutes) * totalKwh;
78	  const total = valleKwh * rates.valle + llanoKwh * rates.llano + puntaKwh * rates.punta;
79	
80	  return { valleKwh, llanoKwh, puntaKwh, total };
81	}
