1	/**
2	 * Motor de cálculo de la tarifa Residencial Triple Horaria de UTE.
3	 *
4	 * Simplificación conocida y documentada (Fase 6/14): UTE trata los feriados como fin de
5	 * semana (sin franja Punta), pero acá no hay calendario de feriados de Uruguay todavía —
6	 * un feriado entre semana se clasificará como día hábil. Corregible más adelante sumando
7	 * un calendario de feriados sin tocar el resto del motor.
8	 */
9	
10	export interface TariffRates {
11	  valle: number;
12	  llano: number;
13	  punta: number;
14	}
15	
16	export type RateClass = 'valle' | 'llano' | 'punta';
17	
18	export interface ChargeBreakdown {
19	  valleKwh: number;
20	  llanoKwh: number;
21	  puntaKwh: number;
22	  total: number;
23	}
24	
25	/** Pliego Tarifario UTE, vigente desde el 01/01/2026 (precios en $/kWh). */
26	export const UTE_2026_RATES: TariffRates = { valle: 2.443, llano: 5.172, punta: 12.034 };
27	
28	/** Franja Punta por defecto: 19:00–23:00 (el usuario la elige entre 17:00 y 23:00 en Ajustes). */
29	export const DEFAULT_PUNTA_START_HOUR = 19;
30	
31	/**
32	 * Clasifica una hora del día según la tarifa Triple Horario.
33	 * - Valle: 00:00–07:00, todos los días.
34	 * - Punta: 4 horas consecutivas a elección (17:00–23:00), solo días hábiles.
35	 * - Llano: el resto (incluye todo el fin de semana fuera del horario Valle).
36	 */
37	export function classifyHour(date: Date, puntaStartHour: number): RateClass {
38	  const hour = date.getHours();
39	  const day = date.getDay(); // 0 = domingo … 6 = sábado
40	  const isWeekday = day >= 1 && day <= 5;
41	
42	  if (hour >= 0 && hour < 7) return 'valle';
43	  if (isWeekday && hour >= puntaStartHour && hour < puntaStartHour + 4) return 'punta';
44	  return 'llano';
45	}
46	
47	/**
48	 * Costo de una carga en casa: recorre minuto a minuto el rango [startAt, endAt) clasificando
49	 * cada minuto, y reparte los kWh totales proporcionalmente al tiempo pasado en cada franja
50	 * (asume tasa de carga constante — no hay forma de conocer la potencia instantánea real sin
51	 * monitoreo en vivo del cargador, que quedó fuera de alcance en Fase 12).
52	 */
53	export function computeHomeChargeCost(
54	  startAt: Date,
55	  endAt: Date,
56	  totalKwh: number,
57	  rates: TariffRates,
58	  puntaStartHour: number,
59	): ChargeBreakdown {
60	  const totalMinutes = Math.round((endAt.getTime() - startAt.getTime()) / 60000);
61	  if (totalMinutes <= 0) {
62	    throw new Error('La hora de fin debe ser posterior a la de inicio.');
63	  }
64	  if (totalKwh <= 0) {
65	    throw new Error('Los kWh cargados deben ser mayores a cero.');
66	  }
67	
68	  const minutesByClass: Record<RateClass, number> = { valle: 0, llano: 0, punta: 0 };
69	  const cursor = new Date(startAt);
70	  for (let m = 0; m < totalMinutes; m++) {
71	    minutesByClass[classifyHour(cursor, puntaStartHour)]++;
72	    cursor.setMinutes(cursor.getMinutes() + 1);
73	  }
74	
75	  const valleKwh = (minutesByClass.valle / totalMinutes) * totalKwh;
76	  const llanoKwh = (minutesByClass.llano / totalMinutes) * totalKwh;
77	  const puntaKwh = (minutesByClass.punta / totalMinutes) * totalKwh;
78	  const total = valleKwh * rates.valle + llanoKwh * rates.llano + puntaKwh * rates.punta;
79	
80	  return { valleKwh, llanoKwh, puntaKwh, total };
81	}
82	
83	/**
84	 * Costo de una carga pública: tarifa manual del proveedor × kWh cargados, más un cargo fijo
85	 * opcional por sesión. En Uruguay UTE (estatal) cobra cargo fijo; eOne, DMC y Evergo (privados) no.
86	 */
87	export function computePublicChargeCost(pricePerKwh: number, kwh: number, fixedFee = 0): number {
88	  if (kwh <= 0) throw new Error('Los kWh cargados deben ser mayores a cero.');
89	  if (pricePerKwh <= 0) throw new Error('El precio por kWh debe ser mayor a cero.');
90	  if (fixedFee < 0) throw new Error('El cargo fijo no puede ser negativo.');
91	  return pricePerKwh * kwh + fixedFee;
92	}
93

1	/** kWh/100km es la unidad estándar de consumo EV (así se publican las fichas WLTP) — Wh/km solo se usa como unidad de entrada manual en el formulario, más simple de tipear. */
2	export function whKmToKwh100(whKm: number): string {
3	  return (whKm / 10).toFixed(1);
4	}
5	
6	export function autonomyKmFrom(batteryKwh: number, whKm: number): number {
7	  return whKm > 0 ? Math.round(batteryKwh / (whKm / 1000)) : 0;
8	}
9	
10	/** "Autonomía estimada": usa el consumo real si ya hay suficientes tramos, si no cae al homologado — un solo número, sin distinguir la fuente en la UI. */
11	export function estimatedAutonomyKm(vehicle: { batteryKwh: number; consumptionWhKm: number }, real: { whKm: number } | null): number {
12	  return autonomyKmFrom(vehicle.batteryKwh, real?.whKm ?? vehicle.consumptionWhKm);
13	}
14

1	/**
2	 * Motor de estimación de una carga en Casa "en curso" — física real (kW = V×A×η), no un
3	 * sensor: no hay forma de leer la potencia instantánea real del cargador, así que se
4	 * calcula a partir de amperaje/voltaje configurados en Ajustes y se corrige con el
5	 * historial real (ver `computeCalibrationFactor`). Resuelve la ecuación "a qué % llego a
6	 * una hora de corte dada" — no al revés — porque así es como funciona un EVSE real: se
7	 * programa por tiempo/límite de energía, no por % objetivo (ver CLAUDE.md).
8	 */
9	
10	const ETA_AC = 0.92;
11	/** Después de este % de batería el litio entra en fase CV (corriente constante ya no, voltaje sí) y el cargador reduce la potencia — la curva "se achata". */
12	const CC_CV_THRESHOLD_PCT = 80;
13	/** A 100% de batería la tasa de carga cae a este factor de la potencia nominal (aproximación simple de la cola CV). */
14	const CV_TAPER_END_FACTOR = 0.25;
15	
16	export function chargerKw(amps: number, volts: number, eta = ETA_AC): number {
17	  return (volts * amps * eta) / 1000;
18	}
19	
20	function taperFactor(pct: number): number {
21	  if (pct < CC_CV_THRESHOLD_PCT) return 1;
22	  const progress = Math.min(1, (pct - CC_CV_THRESHOLD_PCT) / (100 - CC_CV_THRESHOLD_PCT));
23	  return 1 - progress * (1 - CV_TAPER_END_FACTOR);
24	}
25	
26	export interface EstimateResult {
27	  pct: number;
28	  kwhDelivered: number;
29	}
30	
31	/** Estima % de batería y kWh entregados entre `startAt` y `targetTime`, integrando minuto a minuto (misma idea numérica que `tariff.ts`'s `computeHomeChargeCost`). */
32	export function estimateAtTime(
33	  startPct: number,
34	  startAt: Date,
35	  targetTime: Date,
36	  nominalKw: number,
37	  batteryKwh: number,
38	  calibrationFactor = 1,
39	): EstimateResult {
40	  const totalMinutes = Math.max(0, Math.round((targetTime.getTime() - startAt.getTime()) / 60000));
41	  const maxKwh = batteryKwh - (batteryKwh * startPct) / 100;
42	  const kwhPerMinuteNominal = (nominalKw * calibrationFactor) / 60;
43	
44	  let pct = startPct;
45	  let kwhDelivered = 0;
46	  for (let m = 0; m < totalMinutes; m++) {
47	    if (pct >= 100) break;
48	    kwhDelivered += kwhPerMinuteNominal * taperFactor(pct);
49	    pct = startPct + (kwhDelivered / batteryKwh) * 100;
50	  }
51	  pct = Math.min(100, pct);
52	  kwhDelivered = Math.min(kwhDelivered, maxKwh);
53	  return { pct, kwhDelivered };
54	}
55	
56	export interface CalibrationResult {
57	  factor: number;
58	  sampleCount: number;
59	}
60	
61	interface PastHomeCharge {
62	  startAt: string | null;
63	  endAt: string | null;
64	  startPct: number | null;
65	  endPct: number | null;
66	  kwh: number;
67	}
68	
69	/**
70	 * Compara lo que el motor hubiera estimado (con factor 1, sin calibrar) contra lo que
71	 * realmente se cargó, para cada carga pasada en Casa con % de inicio/fin registrado —
72	 * no hace falta una tabla nueva, se re-deriva de `charges` en cada llamada.
73	 */
74	export function computeCalibrationFactor(
75	  pastHomeCharges: PastHomeCharge[],
76	  nominalKw: number,
77	  batteryKwh: number,
78	): CalibrationResult {
79	  const ratios: number[] = [];
80	  for (const c of pastHomeCharges) {
81	    if (c.startAt == null || c.endAt == null || c.startPct == null || c.endPct == null) continue;
82	    const theoretical = estimateAtTime(c.startPct, new Date(c.startAt), new Date(c.endAt), nominalKw, batteryKwh, 1);
83	    if (theoretical.kwhDelivered <= 0) continue;
84	    ratios.push(c.kwh / theoretical.kwhDelivered);
85	  }
86	  if (ratios.length === 0) return { factor: 1, sampleCount: 0 };
87	  const factor = ratios.reduce((a, b) => a + b, 0) / ratios.length;
88	  return { factor, sampleCount: ratios.length };
89	}
