1	/**
2	 * Precios de carga pública por red (UTE, eOne, DMC, Evergo, Mobility, DISA) desde una fuente NO
3	 * oficial: ningún operador publica esto ellos mismos (confirmado — sus sitios institucionales no
4	 * tienen tarifas). evuruguay.com mantiene un CSV público, compilado a mano por su dueño mirando
5	 * cada app — se usa acá solo como sugerencia editable, nunca como verdad absoluta.
6	 *
7	 * Estrategia en cascada: fetch en vivo -> si falla, el último fetch exitoso guardado en este
8	 * dispositivo -> si nunca hubo uno (primer uso sin red), un snapshot fijo tomado a mano.
9	 */
10	
11	export interface NetworkPriceRow {
12	  empresa: string;
13	  bajada: number;
14	  precioKwh: number;
15	}
16	
17	export type NetworkPriceSource = 'live' | 'cache' | 'fallback';
18	
19	export interface NetworkPricesResult {
20	  rows: NetworkPriceRow[];
21	  source: NetworkPriceSource;
22	  /** epoch ms de cuándo ESTE dispositivo bajó el archivo (live) o lo tenía cacheado (cache) — null si es el snapshot fijo. */
23	  fetchedAt: number | null;
24	  /**
25	   * epoch ms de la última vez que detectamos que el CONTENIDO cambió, comparado contra el fetch
26	   * anterior — no es la fecha real de modificación del archivo (el servidor no manda `Last-Modified`
27	   * y no expone `ETag` vía CORS), es una aproximación acotada a qué tan seguido se abre la app.
28	   * null si es el snapshot fijo o si es la primera vez que se ve este archivo en este dispositivo.
29	   */
30	  changedAt: number | null;
31	}
32	
33	const SOURCE_URL = 'https://evuruguay.com/cargadores_all.csv';
34	const CACHE_KEY = 'carga-ev:network-prices-cache';
35	const FETCH_TIMEOUT_MS = 4000;
36	
37	/** Snapshot tomado a mano el 2026-07-14 desde evuruguay.com/cargadores_all.csv — red de resguardo final. */
38	const FALLBACK_SNAPSHOT: NetworkPriceRow[] = [
39	  { empresa: "UTE 'Rápidos' (CC)", bajada: 132.9, precioKwh: 11.8 },
40	  { empresa: "UTE 'Rápidos' Predios Privados (CC)", bajada: 199.4, precioKwh: 11.8 },
41	  { empresa: "UTE 'Lentos' (AC)", bajada: 54.8, precioKwh: 10.4 },
42	  { empresa: 'Eone', bajada: 0, precioKwh: 18.3 },
43	  { empresa: 'Eone (18 a 23hrs)', bajada: 0, precioKwh: 23.851 },
44	  { empresa: 'DMC (00 a 06hrs)', bajada: 0, precioKwh: 18 },
45	  { empresa: 'DMC (06 a 17hrs)', bajada: 0, precioKwh: 16 },
46	  { empresa: 'DMC (17 a 24hrs)', bajada: 0, precioKwh: 15 },
47	  { empresa: 'Evergo', bajada: 122, precioKwh: 19.52 },
48	  { empresa: 'Mobility CCS2', bajada: 130, precioKwh: 12.5 },
49	  { empresa: 'Mobility CCS2 (18 a 22hrs)', bajada: 130, precioKwh: 25.6 },
50	  { empresa: 'Mobility GBT (18 a 22hrs)', bajada: 130, precioKwh: 30 },
51	  { empresa: 'Mobility GBT (00 a 7hrs)', bajada: 130, precioKwh: 21.6 },
52	  { empresa: 'Mobility GBT', bajada: 130, precioKwh: 26.4 },
53	  { empresa: 'DISA (18 a 22hrs)', bajada: 120, precioKwh: 16 },
54	  { empresa: 'DISA (00 a 07hrs)', bajada: 120, precioKwh: 10 },
55	  { empresa: 'DISA', bajada: 120, precioKwh: 12 },
56	];
57	
58	function parseCsv(text: string): NetworkPriceRow[] {
59	  const lines = text.replace(/^﻿/, '').trim().split(/\r?\n/);
60	  const rows: NetworkPriceRow[] = [];
61	  for (let i = 1; i < lines.length; i++) {
62	    const line = lines[i].trim();
63	    if (!line) continue;
64	    const [empresa, bajadaRaw, precioRaw] = line.split(',');
65	    const bajada = parseFloat(bajadaRaw);
66	    const precioKwh = parseFloat(precioRaw);
67	    if (!empresa || !isFinite(precioKwh)) continue;
68	    rows.push({ empresa: empresa.trim(), bajada: isFinite(bajada) ? bajada : 0, precioKwh });
69	  }
70	  return rows;
71	}
72	
73	interface CacheShape {
74	  fetchedAt: number;
75	  changedAt: number;
76	  rows: NetworkPriceRow[];
77	}
78	
79	function readCache(): CacheShape | null {
80	  try {
81	    const raw = localStorage.getItem(CACHE_KEY);
82	    if (!raw) return null;
83	    return JSON.parse(raw) as CacheShape;
84	  } catch {
85	    return null;
86	  }
87	}
88	
89	function writeCache(cache: CacheShape): void {
90	  try {
91	    localStorage.setItem(CACHE_KEY, JSON.stringify(cache));
92	  } catch {
93	    // localStorage puede fallar (modo privado, cuota llena) — no es crítico, seguimos sin cache
94	  }
95	}
96	
97	function rowsEqual(a: NetworkPriceRow[], b: NetworkPriceRow[]): boolean {
98	  if (a.length !== b.length) return false;
99	  return a.every((row, i) => row.empresa === b[i].empresa && row.bajada === b[i].bajada && row.precioKwh === b[i].precioKwh);
100	}
101	
102	export async function getNetworkPrices(): Promise<NetworkPricesResult> {
103	  try {
104	    const controller = new AbortController();
105	    const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
106	    const res = await fetch(SOURCE_URL, { signal: controller.signal, cache: 'no-store' });
107	    clearTimeout(timer);
108	    if (!res.ok) throw new Error(`HTTP ${res.status}`);
109	    const rows = parseCsv(await res.text());
110	    if (rows.length === 0) throw new Error('CSV vacío o con formato inesperado');
111	
112	    const prev = readCache();
113	    const now = Date.now();
114	    const changedAt = prev && rowsEqual(prev.rows, rows) ? prev.changedAt : now;
115	    writeCache({ fetchedAt: now, changedAt, rows });
116	    return { rows, source: 'live', fetchedAt: now, changedAt };
117	  } catch {
118	    const cached = readCache();
119	    if (cached) return { rows: cached.rows, source: 'cache', fetchedAt: cached.fetchedAt, changedAt: cached.changedAt };
120	    return { rows: FALLBACK_SNAPSHOT, source: 'fallback', fetchedAt: null, changedAt: null };
121	  }
122	}
123	
124	/* ============================
125	   Agrupamiento por red + variantes (horario o tipo de conector)
126	============================ */
127	
128	export interface NetworkVariant {
129	  /** nombre completo tal cual viene en el CSV — esto es lo que se guarda como "red" de la carga. */
130	  empresa: string;
131	  /** lo que diferencia esta variante dentro de su red — ej. "(18 a 23hrs)", "'Lentos' (AC)", o "Estándar" si la red no tiene variantes. */
132	  label: string;
133	  bajada: number;
134	  precioKwh: number;
135	  /** [horaInicio, horaFin) si esta variante aplica solo en una franja horaria — null si no varía por hora. */
136	  timeRange: [number, number] | null;
137	}
138	
139	export interface NetworkGroup {
140	  /** nombre de red para el chip principal — UTE, eOne, DMC, Evergo, Mobility, DISA. */
141	  key: string;
142	  variants: NetworkVariant[];
143	}
144	
145	const NETWORK_DEFS: { key: string; pattern: RegExp }[] = [
146	  { key: 'UTE', pattern: /^UTE/i },
147	  { key: 'eOne', pattern: /^Eone/i },
148	  { key: 'DMC', pattern: /^DMC/i },
149	  { key: 'Evergo', pattern: /^Evergo/i },
150	  { key: 'Mobility', pattern: /^Mobility/i },
151	  { key: 'DISA', pattern: /^DISA/i },
152	];
153	
154	function parseTimeRange(label: string): [number, number] | null {
155	  const m = label.match(/(\d{1,2})\s*a\s*(\d{1,2})\s*hrs/i);
156	  if (!m) return null;
157	  const start = parseInt(m[1], 10);
158	  const end = parseInt(m[2], 10);
159	  return isFinite(start) && isFinite(end) ? [start, end] : null;
160	}
161	
162	/**
163	 * Agrupa las filas del CSV por red reconocida. Filas de redes que no reconocemos (ej. si
164	 * evuruguay.com agrega una nueva mañana) simplemente no generan grupo — no rompen nada, solo no
165	 * aparecen como chip todavía.
166	 */
167	export function groupNetworkRows(rows: NetworkPriceRow[]): NetworkGroup[] {
168	  const groups = new Map<string, NetworkVariant[]>();
169	  for (const row of rows) {
170	    const def = NETWORK_DEFS.find((d) => d.pattern.test(row.empresa));
171	    if (!def) continue;
172	    const rest = row.empresa.replace(def.pattern, '').trim();
173	    const label = rest || 'Estándar';
174	    const variant: NetworkVariant = { empresa: row.empresa, label, bajada: row.bajada, precioKwh: row.precioKwh, timeRange: parseTimeRange(label) };
175	    if (!groups.has(def.key)) groups.set(def.key, []);
176	    groups.get(def.key)!.push(variant);
177	  }
178	  return Array.from(groups.entries()).map(([key, variants]) => ({ key, variants }));
179	}
180	
181	/** Elige la variante que aplica ahora mismo según la hora del dispositivo, con fallback a la variante sin horario si ninguna franja matchea. */
182	export function pickDefaultVariant(group: NetworkGroup, now: Date): NetworkVariant | null {
183	  if (group.variants.length === 0) return null;
184	  const hour = now.getHours();
185	  const timeMatch = group.variants.find((v) => v.timeRange && hour >= v.timeRange[0] && hour < v.timeRange[1]);
186	  if (timeMatch) return timeMatch;
187	  return group.variants.find((v) => !v.timeRange) ?? group.variants[0];
188	}
