1	/** Dibuja un valor de texto como dígitos que "ruedan" tipo odómetro — coherente con el vocabulario de auto que ya usa la app (autonomía, odómetro). */
2	export function renderOdometer(el: HTMLElement, text: string): void {
3	  el.innerHTML = [...text]
4	    .map((ch) => {
5	      if (ch >= '0' && ch <= '9') {
6	        const rows = Array.from({ length: 10 }, (_, n) => `<div>${n}</div>`).join('');
7	        return `<span class="digit-wrap"><span class="digit-track" data-target="${ch}">${rows}</span></span>`;
8	      }
9	      return `<span>${ch}</span>`;
10	    })
11	    .join('');
12	  requestAnimationFrame(() => {
13	    el.querySelectorAll<HTMLElement>('.digit-track').forEach((track) => {
14	      const n = Number(track.dataset.target);
15	      track.style.transform = `translateY(-${n * 1.2}em)`;
16	    });
17	  });
18	}
