314	/**
315	 * Consumo real estimado, "de carga a carga" con odómetro — misma lógica que medir el consumo de
316	 * nafta entre tanque y tanque: los kWh cargados en la carga B ≈ energía consumida manejando entre
317	 * el odómetro de A y el de B. Se promedian todos los tramos válidos disponibles.
318	 *
319	 * Aproximación conocida: no separa pérdidas de carga ni autoconsumo en reposo — alcanza para una
320	 * estimación personal, no es un dato de laboratorio.
321	 */
322	export function getRealConsumption(db: OpfsSAHPoolDatabase): RealConsumption | null {
323	  const rows = queryRows<{ odometer_km: number; kwh: number }>(
324	    db,
325	    `SELECT odometer_km, kwh FROM charges
326	     WHERE odometer_km IS NOT NULL
327	     ORDER BY COALESCE(start_at, created_at) ASC`,
328	  );
329	  if (rows.length < 2) return null;
330	
331	  const perKmSamples: number[] = [];
332	  for (let i = 1; i < rows.length; i++) {
333	    const kmDelta = rows[i].odometer_km - rows[i - 1].odometer_km;
334	    if (kmDelta > 0) {
335	      perKmSamples.push((rows[i].kwh / kmDelta) * 1000);
336	    }
337	  }
338	  if (perKmSamples.length === 0) return null;
339	
340	  const whKm = perKmSamples.reduce((a, b) => a + b, 0) / perKmSamples.length;
341	  return { whKm, sampleCount: perKmSamples.length };
342	}
