2	import { queryRows } from './query-helper';
3	import { computeHomeChargeCost, computePublicChargeCost, type TariffRates } from '../tariff';
4	
5	export type ChargeLocation = 'home' | 'public';
6	
7	export interface NewHomeCharge {
8	  location: 'home';
9	  startAt: Date;
10	  endAt: Date;
11	  kwh: number;
12	  odometerKm: number | null;
13	  /** % de batería al iniciar/terminar — decimal real (24.7, no redondeado), null si vino del modo rápido sin ese dato. */
14	  startPct?: number | null;
15	  endPct?: number | null;
16	}
17	export interface NewPublicCharge {
18	  location: 'public';
19	  kwh: number;
20	  pricePerKwh: number;
21	  odometerKm: number | null;
22	  fixedFee: number | null;
23	  /** "UTE", "Otro", o el nombre completo de la variante sugerida (ej. "DMC (17 a 24hrs)") — ver src/lib/network-prices.ts. */
24	  network: string | null;
25	  /** Día real en que ocurrió la carga — antes no existía ningún campo de fecha para Público, así
26	   * que start_at quedaba null y getRealConsumption() caía al created_at (el día en que se cargó el
27	   * registro, no el día real de la carga), rompiendo el orden cronológico usado para el consumo real. */
28	  chargeDate: Date;
29	}
30	export type NewCharge = NewHomeCharge | NewPublicCharge;
31	
32	export interface Charge {
33	  id: number;
34	  location: ChargeLocation;
35	  startAt: string | null;
36	  endAt: string | null;
37	  kwh: number;
38	  odometerKm: number | null;
39	  pricePerKwh: number | null;
40	  fixedFee: number | null;
41	  network: string | null;
42	  cost: number;
43	  valleKwh: number;
44	  llanoKwh: number;
45	  puntaKwh: number;
46	  createdAt: string;
47	  startPct: number | null;
48	  endPct: number | null;
49	}
50	
51	interface ChargeRow {
52	  id: number;
53	  location: string;
54	  start_at: string | null;
55	  end_at: string | null;
56	  kwh: number;
57	  odometer_km: number | null;
58	  price_per_kwh: number | null;
59	  fixed_fee: number | null;
60	  network: string | null;
61	  cost: number;
62	  breakdown_valle_kwh: number;
63	  breakdown_llano_kwh: number;
64	  breakdown_punta_kwh: number;
65	  created_at: string;
66	  start_pct: number | null;
67	  end_pct: number | null;
68	}
69	
70	function fromRow(row: ChargeRow): Charge {
71	  return {
72	    id: row.id,
73	    location: row.location as ChargeLocation,
74	    startAt: row.start_at,
75	    endAt: row.end_at,
76	    kwh: row.kwh,
77	    odometerKm: row.odometer_km,
78	    pricePerKwh: row.price_per_kwh,
79	    fixedFee: row.fixed_fee,
80	    network: row.network,
81	    cost: row.cost,
82	    valleKwh: row.breakdown_valle_kwh,
83	    llanoKwh: row.breakdown_llano_kwh,
84	    puntaKwh: row.breakdown_punta_kwh,
85	    createdAt: row.created_at,
86	    startPct: row.start_pct,
87	    endPct: row.end_pct,
88	  };
89	}
90	
91	/** Inserta una carga calculando el costo con el motor de tarifas — nunca se confía en un costo pasado desde la UI. */
92	export function insertCharge(
93	  db: OpfsSAHPoolDatabase,
94	  input: NewCharge,
95	  rates: TariffRates,
96	  puntaStartHour: number,
97	): Charge {
98	  let cost: number, valleKwh: number, llanoKwh: number, puntaKwh: number;
99	  let startAt: string | null = null, endAt: string | null = null, pricePerKwh: number | null = null;
100	  let fixedFee: number | null = null, network: string | null = null;
101	  let startPct: number | null = null, endPct: number | null = null;
102	
103	  if (input.location === 'home') {
104	    const b = computeHomeChargeCost(input.startAt, input.endAt, input.kwh, rates, puntaStartHour);
105	    cost = b.total; valleKwh = b.valleKwh; llanoKwh = b.llanoKwh; puntaKwh = b.puntaKwh;
106	    startAt = input.startAt.toISOString();
107	    endAt = input.endAt.toISOString();
108	    startPct = input.startPct ?? null;
109	    endPct = input.endPct ?? null;
110	  } else {
111	    cost = computePublicChargeCost(input.pricePerKwh, input.kwh, input.fixedFee ?? 0);
112	    valleKwh = 0; llanoKwh = 0; puntaKwh = 0;
113	    pricePerKwh = input.pricePerKwh;
114	    fixedFee = input.fixedFee;
115	    network = input.network;
116	    startAt = input.chargeDate.toISOString();
117	  }
118	
119	  db.exec(
120	    `INSERT INTO charges
121	       (location, start_at, end_at, kwh, odometer_km, price_per_kwh, fixed_fee, network, cost,
122	        breakdown_valle_kwh, breakdown_llano_kwh, breakdown_punta_kwh, start_pct, end_pct)
123	     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
124	    { bind: [input.location, startAt, endAt, input.kwh, input.odometerKm, pricePerKwh, fixedFee, network, cost, valleKwh, llanoKwh, puntaKwh, startPct, endPct] },
125	  );
126	
127	  const rows = queryRows<ChargeRow>(db, 'SELECT * FROM charges WHERE id = last_insert_rowid()');
128	  return fromRow(rows[0]);
129	}
130	
131	/**
132	 * Actualiza una carga existente, recalculando el costo con las tarifas de HOY — no con las que
133	 * regían cuando se registró originalmente (no guardamos qué tarifa estaba vigente en cada
134	 * momento, solo el resultado). Es la misma decisión documentada en el wireframe de este agregado.
135	 */
136	export function updateCharge(
137	  db: OpfsSAHPoolDatabase,
138	  id: number,
139	  input: NewCharge,
140	  rates: TariffRates,
141	  puntaStartHour: number,
142	): Charge {
143	  let cost: number, valleKwh: number, llanoKwh: number, puntaKwh: number;
144	  let startAt: string | null = null, endAt: string | null = null, pricePerKwh: number | null = null;
145	  let fixedFee: number | null = null, network: string | null = null;
146	  let startPct: number | null = null, endPct: number | null = null;
147	
148	  if (input.location === 'home') {
149	    const b = computeHomeChargeCost(input.startAt, input.endAt, input.kwh, rates, puntaStartHour);
150	    cost = b.total; valleKwh = b.valleKwh; llanoKwh = b.llanoKwh; puntaKwh = b.puntaKwh;
151	    startAt = input.startAt.toISOString();
152	    endAt = input.endAt.toISOString();
153	    startPct = input.startPct ?? null;
154	    endPct = input.endPct ?? null;
155	  } else {
156	    cost = computePublicChargeCost(input.pricePerKwh, input.kwh, input.fixedFee ?? 0);
157	    valleKwh = 0; llanoKwh = 0; puntaKwh = 0;
158	    pricePerKwh = input.pricePerKwh;
159	    fixedFee = input.fixedFee;
160	    network = input.network;
161	    startAt = input.chargeDate.toISOString();
162	  }
163	
164	  db.exec(
165	    `UPDATE charges SET
166	       location = ?, start_at = ?, end_at = ?, kwh = ?, odometer_km = ?, price_per_kwh = ?, fixed_fee = ?, network = ?, cost = ?,
167	       breakdown_valle_kwh = ?, breakdown_llano_kwh = ?, breakdown_punta_kwh = ?, start_pct = ?, end_pct = ?
168	     WHERE id = ?`,
