213	export interface PeriodStats {
214	  totalCost: number;
215	  count: number;
216	  avgCostPerKwh: number;
217	  valleSharePct: number;
218	  llanoSharePct: number;
219	  puntaSharePct: number;
220	  /** null si hay menos de 2 lecturas de odómetro en el período — no se puede estimar. */
221	  costPerKm: number | null;
