224	/** Estadísticas para el dashboard, sobre las cargas desde `sinceIso` (inclusive). */
225	export function getStatsSince(db: OpfsSAHPoolDatabase, sinceIso: string): PeriodStats {
226	  const rows = queryRows<{
227	    total_cost: number | null;
228	    count: number;
229	    total_kwh: number | null;
230	    valle: number | null;
231	    llano: number | null;
232	    punta: number | null;
233	    min_odo: number | null;
234	    max_odo: number | null;
235	    odo_count: number;
236	  }>(
237	    db,
238	    `SELECT
239	       SUM(cost) AS total_cost,
240	       COUNT(*) AS count,
241	       SUM(kwh) AS total_kwh,
242	       SUM(breakdown_valle_kwh) AS valle,
243	       SUM(breakdown_llano_kwh) AS llano,
244	       SUM(breakdown_punta_kwh) AS punta,
245	       MIN(odometer_km) AS min_odo,
246	       MAX(odometer_km) AS max_odo,
247	       COUNT(odometer_km) AS odo_count
248	     FROM charges
249	     WHERE COALESCE(start_at, created_at) >= ?`,
250	    [sinceIso],
251	  );
252	  const r = rows[0];
253	  const totalCost = r?.total_cost ?? 0;
254	  const totalKwh = r?.total_kwh ?? 0;
255	  const homeKwh = (r?.valle ?? 0) + (r?.llano ?? 0) + (r?.punta ?? 0);
256	  const km = (r?.odo_count ?? 0) >= 2 && r?.max_odo != null && r?.min_odo != null ? r.max_odo - r.min_odo : 0;
257	  return {
258	    totalCost,
259	    count: r?.count ?? 0,
260	    avgCostPerKwh: totalKwh > 0 ? totalCost / totalKwh : 0,
261	    valleSharePct: homeKwh > 0 ? ((r?.valle ?? 0) / homeKwh) * 100 : 0,
262	    llanoSharePct: homeKwh > 0 ? ((r?.llano ?? 0) / homeKwh) * 100 : 0,
263	    puntaSharePct: homeKwh > 0 ? ((r?.punta ?? 0) / homeKwh) * 100 : 0,
264	    costPerKm: km > 0 ? totalCost / km : null,
265	  };
266	}
