273	/** Gasto total por mes, para el gráfico de tendencia — de más viejo a más nuevo. */
274	export function getMonthlyTotals(db: OpfsSAHPoolDatabase, monthsBack: number): MonthlyTotal[] {
275	  const now = new Date();
276	  const out: MonthlyTotal[] = [];
277	  for (let i = monthsBack - 1; i >= 0; i--) {
278	    const monthDate = new Date(now.getFullYear(), now.getMonth() - i, 1);
279	    const start = monthDate.toISOString();
280	    const end = new Date(monthDate.getFullYear(), monthDate.getMonth() + 1, 1).toISOString();
281	    const rows = queryRows<{ total: number | null }>(
282	      db,
283	      `SELECT SUM(cost) AS total FROM charges
284	       WHERE COALESCE(start_at, created_at) >= ? AND COALESCE(start_at, created_at) < ?`,
285	      [start, end],
286	    );
287	    out.push({ monthLabel: monthDate.toLocaleDateString('es-UY', { month: 'short' }), total: rows[0]?.total ?? 0 });
288	  }
289	  return out;
290	}
