292	/** Gasto por día del mes en curso (1..hoy), para la mini-gráfica del hero de Inicio — 0 en los días sin carga. */
293	export function getDailyTotalsThisMonth(db: OpfsSAHPoolDatabase): number[] {
294	  const now = new Date();
295	  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
296	  const today = now.getDate();
297	  const rows = queryRows<{ day: number; total: number | null }>(
298	    db,
299	    `SELECT CAST(strftime('%d', COALESCE(start_at, created_at)) AS INTEGER) AS day, SUM(cost) AS total
300	     FROM charges
301	     WHERE COALESCE(start_at, created_at) >= ?
302	     GROUP BY day`,
303	    [monthStart.toISOString()],
304	  );
305	  const byDay = new Map(rows.map((r) => [r.day, r.total ?? 0]));
306	  return Array.from({ length: today }, (_, i) => byDay.get(i + 1) ?? 0);
307	}
