1	import type { OpfsSAHPoolDatabase } from '@sqlite.org/sqlite-wasm';
2	import { queryRows } from './query-helper';
3	import { SETTINGS_KEYS } from './schema';
4	import type { TariffRates } from '../tariff';
5	import { DEFAULT_PERSONALIZACION, hexToHue, type PersonalizacionConfig } from '../personalizacion';
6	
7	export interface AppSettings {
8	  tariffValle: number;
9	  tariffLlano: number;
10	  tariffPunta: number;
11	  puntaStartHour: number;
12	  notifBackupEnabled: boolean;
13	  theme: 'auto' | 'light' | 'dark';
14	  accentColor: string;
15	  personalizacion: PersonalizacionConfig;
16	  /** Amperaje/voltaje reales del cargador de Casa (ej. 24A/226V) — usados por src/lib/estimation.ts para calcular kW. */
17	  homeChargerAmps: number;
18	  homeChargerVolts: number;
19	  /** Ubicación de Casa para el futuro aviso de geofencing — null hasta que el usuario la guarde una vez. */
20	  homeLat: number | null;
21	  homeLng: number | null;
22	}
23	
24	/** Si ya existe `personalizacion` guardada, se usa tal cual (con merge de defaults por si se agregó un campo nuevo). Si no, se migra una única vez desde el `accentColor` hex del viejo sistema de 5 swatches, para no perder el color elegido. */
25	function resolvePersonalizacion(raw: string | undefined, accentColor: string): PersonalizacionConfig {
26	  if (raw) {
27	    try {
28	      return { ...DEFAULT_PERSONALIZACION, ...(JSON.parse(raw) as Partial<PersonalizacionConfig>) };
29	    } catch {
30	      // JSON corrupto — cae al default/migración de abajo
31	    }
32	  }
33	  // hue2 se deriva por armonía (complementario, el default de `linked`), no igual a hue — si no,
34	  // la aurora de todo usuario migrado quedaría monocromática en vez de a dos tonos.
35	  const hue = hexToHue(accentColor);
36	  const hue2 = (hue + DEFAULT_PERSONALIZACION.harmony) % 360;
37	  return { ...DEFAULT_PERSONALIZACION, hue, hue2 };
38	}
39	
40	export function getSettings(db: OpfsSAHPoolDatabase): AppSettings {
41	  const rows = queryRows<{ key: string; value: string }>(db, 'SELECT key, value FROM settings');
42	  const map = Object.fromEntries(rows.map((r) => [r.key, r.value]));
43	  const accentColor = map[SETTINGS_KEYS.accentColor] || '#1F8FE0';
44	  return {
45	    tariffValle: Number(map[SETTINGS_KEYS.tariffValle]),
46	    tariffLlano: Number(map[SETTINGS_KEYS.tariffLlano]),
47	    tariffPunta: Number(map[SETTINGS_KEYS.tariffPunta]),
48	    puntaStartHour: Number(map[SETTINGS_KEYS.puntaStartHour]),
49	    notifBackupEnabled: map[SETTINGS_KEYS.notifBackupEnabled] === '1',
50	    theme: (map[SETTINGS_KEYS.theme] as AppSettings['theme']) ?? 'auto',
51	    accentColor,
52	    personalizacion: resolvePersonalizacion(map[SETTINGS_KEYS.personalizacion], accentColor),
53	    homeChargerAmps: Number(map[SETTINGS_KEYS.homeChargerAmps]) || 0,
54	    homeChargerVolts: Number(map[SETTINGS_KEYS.homeChargerVolts]) || 0,
55	    homeLat: map[SETTINGS_KEYS.homeLat] ? Number(map[SETTINGS_KEYS.homeLat]) : null,
56	    homeLng: map[SETTINGS_KEYS.homeLng] ? Number(map[SETTINGS_KEYS.homeLng]) : null,
57	  };
58	}
59	
60	export function getTariffRates(db: OpfsSAHPoolDatabase): TariffRates {
61	  const s = getSettings(db);
62	  return { valle: s.tariffValle, llano: s.tariffLlano, punta: s.tariffPunta };
63	}
