65	export function setSetting(db: OpfsSAHPoolDatabase, key: string, value: string): void {
66	  db.exec('INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value', {
67	    bind: [key, value],
68	  });
69	}
