const DAY = 864e5;
/** Período del resumen: 30 días corridos (vs los 30 anteriores) o mes calendario (vs el mismo tramo del mes anterior). */
function period(now) {
  const end = new Date(now.getTime() + 1);
  if (gPeriod === 'mes') {
    const from = L.startOfMonth(now), c = L.compareToPrevMonth(S.charges, now);
    return { from, end, cmp: c, vs: `el mismo tramo de ${MONTHS[L.startOfMonth(now, 1).getMonth()]}` };
  }
  const from = new Date(now.getTime() - 30 * DAY), prev = L.statsBetween(S.charges, new Date(now.getTime() - 60 * DAY), from).total;
  const cur = L.statsBetween(S.charges, from, end).total;
  return { from, end, cmp: { cur, prev, deltaPct: prev > 0 ? ((cur - prev) / prev) * 100 : null }, vs: 'los 30 días anteriores' };
}

function renderGasto() {
  const now = new Date(), p = period(now), cmp = p.cmp;
  const s = L.statsBetween(S.charges, p.from, p.end);
  const m6 = L.monthlyTotals(S.charges, now, 6), mx = Math.max(...m6.map((x) => x.total), 1);
  const saved = S.charges.filter((c) => new Date(c.startAt) >= p.from).reduce((a, c) => a + (c.location === 'home' ? L.valleSavings(c, S.rates) : 0), 0);
  const pct = (a, b) => (b > 0 ? Math.round((a / b) * 100) : 0);
  let h = `<div class="seg wide" role="group" aria-label="Período"><button data-gp="30d" aria-pressed="${gPeriod === '30d'}">30 días</button><button data-gp="mes" aria-pressed="${gPeriod === 'mes'}">Este mes</button></div>`;
  h += `<div class="hero2"><p class="big"><span class="cur">$</span>${int(s.total)}</p><p class="sub">${int(s.kwh)} kWh · ${s.count} ${s.count === 1 ? 'carga' : 'cargas'}</p>`;
  if (cmp.deltaPct != null) h += `<p class="find">${cmp.deltaPct >= 0 ? '↑' : '↓'} ${Math.abs(Math.round(cmp.deltaPct))}% frente a ${p.vs} (${money(cmp.prev)}).</p>`;
  h += `</div>`;

