const c=window.__carga; const wait=(ms)=>new Promise(r=>setTimeout(r,ms)); const q=(s)=>document.querySelector(s);
while(document.querySelector('.fn.open')) { c.closeFn(); await wait(100); }
await wait(400);
const before=c.S.charges.length;
c.openFn('cargar'); await wait(900);
q('#kindSeg [data-kind="public"]').click(); await wait(200);
const pubKwh = q('#costLine').innerText+' | '+q('#ctxLine').innerText;
q('#modeBtn').click(); await wait(600);
const pct = q('#valNum').innerText+q('#valUnit').innerText+' | '+q('#costLine').innerText+' | '+q('#ctxLine').innerText;
// abrir detalles y ver campos
q('#detBtn').click(); await wait(900);
const det = q('#detForm').innerText.replace(/\n+/g,' | ');
const odo = q('#d-odo'); odo.value='16700'; odo.dispatchEvent(new Event('input',{bubbles:true}));
const from = q('#d-from'); from.value='25'; from.dispatchEvent(new Event('input',{bubbles:true}));
await wait(200);
const afterDet = q('#costLine').innerText+' | '+q('#ctxLine').innerText;
c.closeFn(); await wait(600);
// guardar tocando la ficha central
const slots=[...document.querySelectorAll('#kRail .slot')]; const idx=Math.round(q('#kRail').scrollLeft/100); slots[idx].click(); await wait(900);
const last=c.S.charges[c.S.charges.length-1];
JSON.stringify({before, after:c.S.charges.length, pubKwh, pct, det, afterDet, last, top:q('#topBar').innerText})

