el.addEventListener('scroll', () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(paint); }, { passive: true });
el.addEventListener('click', (e) => {
  if (dragged) return;
  const s = e.target.closest('.slot'); if (!s) return;
  const i = +s.dataset.i;
  if (i === at()) onActivate(i); else go(i, true, true);
});
el.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowRight' && at() < count - 1) go(at() + 1, true, true);
  if (e.key === 'ArrowLeft' && at() > 0) go(at() - 1, true, true);
});
// arrastre con mouse (solo vista previa de escritorio)
el.addEventListener('pointerdown', (e) => { if (e.pointerType === 'mouse') md = { x: e.clientX, l: el.scrollLeft, moved: false }; });
addEventListener('pointermove', (e) => {
  if (!md) return;
  const dx = e.clientX - md.x;
  if (!md.moved && Math.abs(dx) > 5) { md.moved = true; el.classList.add('mouse-drag'); }
  if (md.moved) el.scrollLeft = md.l - dx;
});
addEventListener('pointerup', () => {
  if (!md) return;
  const m = md; md = null;
  if (!m.moved) return;
  el.classList.remove('mouse-drag');
  dragged = true; setTimeout(() => (dragged = false), 0);
  el.scrollTo({ left: Math.round(el.scrollLeft / SLOT) * SLOT, behavior: 'smooth' });
});

