474	    const g = groups().find((x) => x.key === K.netKey);
475	    return g ? g.variants[Math.min(K.varIdx, g.variants.length - 1)] : null;
476	  }
477	  function pickNet(now) {
478	    const rank = L.rankNetworks(groups(), now, Math.max(kwhNow(), 1));
479	    const g = groups().find((x) => x.key === K.netKey) || groups().find((x) => x.key === 'UTE') || groups()[0];
480	    if (!g) return;
481	    K.netKey = g.key;
482	    const v = L.pickVariant(g, now);
483	    K.varIdx = Math.max(0, g.variants.indexOf(v));
484	    if (!K.priceTouched && v) { K.price = String(v.price); K.fee = String(v.fee); }
485	    return rank;
