/* ================= Registrar carga ================= */
const KWH_CHIPS = [5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 60, 70, 80];
const PCT_CHIPS = [40, 50, 60, 70, 80, 90, 100];
const K = { kind: 'home', mode: 'kwh', kwh: 25, from: 20, to: 80, idx: 4, custom: false, start: null, end: null, windowTouched: false, odo: '', netKey: '', varIdx: 0, price: '', fee: '', priceTouched: false, date: null };
let kRail;

const kwhNow = () => (K.mode === 'kwh' ? K.kwh : L.kwhFromPct(K.from, K.to, S.vehicle.batteryKwh) || 0);
const chips = () => (K.mode === 'kwh' ? KWH_CHIPS : PCT_CHIPS);
const chipVal = (i) => chips()[i];
const valTxt = () => (K.mode === 'kwh' ? kwhTxt(K.kwh) : String(Math.round(K.to)));

function buildKRail() {
  if (kRail) kRail.destroy();
  kRail = makeRail($('#kRail'), {
    count: chips().length,
    html: (i) => `<span class="chip-n">${chipVal(i)}</span>`,
    label: (i) => `${chipVal(i)} ${K.mode === 'kwh' ? 'kWh' : '%'}`,
    onChange: (i, byUser) => {
      K.idx = i;
      if (byUser) { K.custom = false; if (K.mode === 'kwh') K.kwh = chipVal(i); else K.to = chipVal(i); recalc(); }
      kRail.relabel((j) => (K.custom && j === i ? valTxt() : chipVal(j)));
    },
    onActivate: () => saveCharge(),
  });
}

function currentVariant() {
  const g = groups().find((x) => x.key === K.netKey);
  return g ? g.variants[Math.min(K.varIdx, g.variants.length - 1)] : null;
}
function pickNet(now) {
  const rank = L.rankNetworks(groups(), now, Math.max(kwhNow(), 1));
  const g = groups().find((x) => x.key === K.netKey) || groups().find((x) => x.key === 'UTE') || groups()[0];
  if (!g) return;
  K.netKey = g.key;
  const v = L.pickVariant(g, now);
  K.varIdx = Math.max(0, g.variants.indexOf(v));
  if (!K.priceTouched && v) { K.price = String(v.price); K.fee = String(v.fee); }
  return rank;
}

function homeWindow() {
  const now = new Date(), kwh = kwhNow(), kw = nominalKw();
  if (!K.windowTouched) {
    let mins = 120;
    if (kwh > 0 && kw > 0) mins = Math.max(10, K.mode === 'pct' ? L.minutesToDeliver(K.from, kwh, kw, S.vehicle.batteryKwh, calibration().factor) || 120 : Math.ceil((kwh / kw) * 60));
    K.end = now; K.start = new Date(now.getTime() - mins * 60000);
  }
  return { start: K.start, end: K.end };
}

/** Calcula el costo con el motor y actualiza la pantalla (nunca guarda un costo tipeado a mano). */
function recalc() {
  $('#valNum').textContent = valTxt();
  $('#valUnit').textContent = K.mode === 'kwh' ? 'kWh' : '%';
  const kwh = kwhNow(), cost = $('#costLine'), ctx = $('#ctxLine'), bar = $('#kBar');
  bar.innerHTML = '';
  let calc = null;
  try {
