      const r = L.computeHomeChargeCost(w.start, w.end, kwh, S.rates, S.puntaStart, { nominalKw: nominalKw(), calibration: calibration().factor, startPct: K.mode === 'pct' ? K.from : null, batteryKwh: S.vehicle.batteryKwh });
      calc = { cost: r.total, ...r };
      cost.textContent = money(r.total);
      ctx.textContent = `${kwhTxt(kwh)} kWh · de ${hhmm(w.start)} a ${hhmm(r.finishedAt)}`;
      bar.innerHTML = bands(r.valleKwh, r.llanoKwh, r.puntaKwh);
