      const price = num(K.price), fee = num(K.fee) || 0;
      const total = L.computePublicChargeCost(price, kwh, fee);
      calc = { cost: total };
      cost.textContent = money(total);
      const v = currentVariant();
      ctx.textContent = `${kwhTxt(kwh)} kWh × ${money2(price)}${fee > 0 ? ` + ${money(fee)} fijo` : ''}${v ? ` · ${K.netKey}` : ''}`;
