  const k = 10 ** max;
  const [i, f0 = ''] = (Math.round(n * k) / k).toFixed(max).split('.');
  let f = f0.replace(/0+$/, '');
  while (f.length < min) f += '0';
  return f ? `${i},${f}` : i;
}
