/* ================= Cuándo empezar ================= */
const P = { from: 20, to: 80, atMin: 420 };
function initProg() {
  const last = [...S.charges].sort((a, b) => new Date(b.startAt) - new Date(a.startAt))[0];
  P.from = 20; P.to = last && last.endPct && last.endPct > 60 ? Math.min(100, Math.round(last.endPct / 5) * 5) : 80; P.atMin = 420;
}
const GAP = 0.5; // % mínimo entre el inicio y el final
const setFrom = (v) => { P.from = r1(Math.max(0, Math.min(P.to - GAP, v))); };
const setTo = (v) => { P.to = r1(Math.max(P.from + GAP, Math.min(100, v))); };
document.querySelectorAll('[data-s]').forEach((b) => holdRepeat(b, (mult) => {
  const k = b.dataset.s, d = +b.dataset.d;
  if (k === 'from') setFrom(P.from + d * mult);
  if (k === 'to') setTo(P.to + d * mult);
  if (k === 'at') P.atMin = (P.atMin + d + 1440) % 1440;
  renderProg();
}));
[['o-from', setFrom], ['o-to', setTo]].forEach(([id, set]) => {
  const el = $('#' + id);
  el.addEventListener('focus', () => el.select());
  el.addEventListener('change', () => { const v = num(el.value); if (isFinite(v)) set(v); renderProg(); });
  el.addEventListener('keydown', (e) => { if (e.key === 'Enter') el.blur(); });
});
function renderProg() {
  $('#o-from').value = pctTxt(P.from) + '%'; $('#o-to').value = pctTxt(P.to) + '%';
  $('#o-at').textContent = `${String(Math.floor(P.atMin / 60)).padStart(2, '0')}:${String(P.atMin % 60).padStart(2, '0')}`;
  const now = new Date();
  let deadline = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, P.atMin);
  if (deadline <= now) deadline = new Date(deadline.getTime() + 864e5);
  const calib = calibration().factor, kw = nominalKw();
  const altStart = new Date(deadline.getFullYear(), deadline.getMonth(), deadline.getDate() - 1, S.puntaStart, 0);
  const s = L.suggestStart({ fromPct: P.from, toPct: P.to, deadline, nominalKw: kw, batteryKwh: S.vehicle.batteryKwh, calibration: calib, rates: S.rates, puntaStart: S.puntaStart, altStart: altStart > now ? altStart : now });
  const out = $('#pAlt');
  if (!s) { $('#pStart').textContent = '—'; $('#pSub').textContent = 'Configurá tu cargador en Autonomía.'; $('#pFind').textContent = ''; out.innerHTML = ''; return; }
  const h = Math.floor(s.minutes / 60), m = s.minutes % 60;
  $('#pStart').textContent = hhmm(s.start);
  $('#pSub').textContent = `${kwhTxt(s.kwh)} kWh · ${h} h ${m} min · terminás a las ${hhmm(deadline)}`;
  $('#pFind').textContent = s.valleShare >= 0.995 ? `Todo en Valle: ${money(s.best.total)}.`
    : `${Math.round(s.valleShare * 100)}% en Valle: ${money(s.best.total)}. Con menos carga o terminando más tarde entra todo en Valle.`;
  let alt = '';
  if (s.alt) {
    const late = s.alt.finishedAt > deadline;
    alt += `<div class="kv"><span>Si empezás ${s.alt.start === now ? 'ahora' : 'a las ' + hhmm(s.alt.start)}<em>termina ${hhmm(s.alt.finishedAt)}${late ? `, después de las ${hhmm(deadline)}` : ''}</em></span><b>${money(s.alt.total)}</b></div>`;
  }
  if (s.alt && s.alt.total > s.best.total + 0.5) alt += `<p class="note">Ahorrás ${money(s.alt.total - s.best.total)} en esta carga.</p>`;
  const est = L.estimateAtTime(P.from, now, deadline, kw, S.vehicle.batteryKwh, calib);
  alt += `<h3>Si la dejás cargando ahora</h3><div class="kv"><span>Llegás a las ${hhmm(deadline)} con</span><b>≈ ${Math.round(est.pct)}%</b></div><div class="kv"><span>Energía</span><b>${kwhTxt(est.kwhDelivered)} kWh</b></div>`;
  alt += `<p class="note">Potencia estimada ${dec(kw, 1)} kW (${S.amps} A × ${S.volts} V, rendimiento 92%)${calibration().samples ? ` calibrada con ${calibration().samples} cargas` : ''}. Pasado el 80% la carga se hace más lenta.</p>`;
  out.innerHTML = alt;
}

