1	import type { OpfsSAHPoolDatabase } from '@sqlite.org/sqlite-wasm';
2	import { queryRows } from './query-helper';
3	
4	export interface ActiveCharge {
5	  mode: 'scheduled' | 'live';
6	  startAt: string;
7	  targetStopAt: string;
8	  startPct: number;
9	}
10	
11	interface ActiveChargeRow {
12	  mode: string;
13	  start_at: string;
14	  target_stop_at: string;
15	  start_pct: number;
16	}
17	
18	export function getActiveCharge(db: OpfsSAHPoolDatabase): ActiveCharge | null {
19	  const rows = queryRows<ActiveChargeRow>(db, 'SELECT * FROM active_charge WHERE id = 1');
20	  const row = rows[0];
21	  if (!row) return null;
22	  return {
23	    mode: row.mode as ActiveCharge['mode'],
24	    startAt: row.start_at,
25	    targetStopAt: row.target_stop_at,
26	    startPct: row.start_pct,
27	  };
