  datePublicInput.value = todayDateInput();
  priceInput.value = '';
  kwhPublicInput.value = '';
  odoPublicInput.value = '';
  pctFromHome.value = '';
  pctToHome.value = '';
  pctFromPublic.value = '';
  pctToPublic.value = '';
  mode = 'kwh';

