  $('#list').innerHTML = seg + ([...gs].map(([m, rows]) => `<p class="month">${cap(m)}</p><ul>${rows.map(li).join('')}</ul>`).join('') || '<p class="note">No hay cargas para mostrar.</p>');
}
$('#list').addEventListener('click', (e) => {
  const f = e.target.closest('[data-hf]'), d = e.target.closest('[data-del]'), row = e.target.closest('.row');
  if (f) { hFilter = f.dataset.hf; hSel = null; renderList(); }
  else if (d) { if (confirm('¿Eliminar esta carga? No se puede deshacer.')) { S.charges = S.charges.filter((c) => c.id !== Number(d.dataset.del)); hSel = null; persist(); renderAll(); } }
  else if (row) { hSel = hSel === Number(row.dataset.id) ? null : Number(row.dataset.id); renderList(); }
});

