    view: () => { const p = planCalc(new Date(), false); return { num: mm(W.stopMin), ctx: p.cost ? `Si empezás ahora llegás a ≈ ${pctTxt(p.est.pct)}% · ${kwhTxt(p.est.kwhDelivered)} kWh · ${money(p.cost.total)}` : '' }; } },
