        + (p.cost ? row('Costo estimado', money(p.cost.total), `${Math.round((p.cost.valleKwh / p.est.kwhDelivered) * 100)}% en Valle`) : '') + row('Autonomía', `≈ ${a.km} km`, W.odo != null ? `odómetro ${int(W.odo)} km` : '') };
