/* Historial: Libro mayor por fecha + Calendario (todo con alcance #hist) */
#hist { --valle: #4fb58a; --llano: #8e8e93; --punta: #fff; --line: #1a1a1a; }
#hist .hh { flex: none; padding: 0 20px; }
#hist .hsub { margin-top: 2px; font-size: 14px; line-height: 1.3; color: var(--ink-2); }
#hist .hsub b { font-weight: 500; color: var(--ink); }
#hist .htabs { display: flex; gap: 22px; margin-top: 8px; border-bottom: 1px solid var(--line); font-size: 14px; color: var(--ink-2); }
#hist .htabs button { height: 44px; margin-bottom: -1px; }
#hist .htabs button[aria-pressed="true"] { color: var(--ink); box-shadow: inset 0 -2px 0 var(--ink); }
#hist .hscroll { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 0 20px calc(var(--safe-bottom) + 24px); }
#hist .hscroll::-webkit-scrollbar { display: none; }
#hist .legend { display: flex; gap: 14px; margin-top: 12px; font-size: 12px; color: var(--ink-2); white-space: nowrap; }
#hist .legend span::before { content: ""; display: inline-block; width: 8px; height: 8px; margin-right: 6px; vertical-align: -0.5px; }
#hist .legend .l1::before { background: var(--valle); } #hist .legend .l2::before { background: var(--llano); } #hist .legend .l3::before { background: var(--punta); } #hist .legend .l4::before { box-shadow: inset 0 0 0 1.5px var(--llano); }
#hist .stackh { display: flex; gap: 1px; height: 100%; width: 100%; }
#hist .stackh i, #hist .stackv i { display: block; min-width: 1px; }
#hist .stackv { display: flex; flex-direction: column-reverse; gap: 1px; width: 100%; height: 100%; }
#hist .stackv i { min-height: 1px; }
#hist .v1 { background: var(--valle); } #hist .v2 { background: var(--llano); } #hist .v3 { background: var(--punta); }
#hist .outl { width: 100%; height: 100%; box-shadow: inset 0 0 0 1.5px var(--llano); }

/* detalle de una carga */
#hist .det { padding: 6px 0 14px; }
#hist .det .dk { display: flex; justify-content: space-between; gap: 12px; padding: 7px 0; font-size: 14px; }
#hist .det .dk span { color: var(--ink-2); }
#hist .det .dk b { font-weight: 500; text-align: right; }
#hist .det .dk em { color: var(--ink-2); font-style: normal; font-weight: 400; margin-left: 6px; }
#hist .det .dbar { height: 5px; margin: 4px 0 6px; }
#hist .det .ddel { margin-top: 6px; height: 40px; padding: 0 14px; border-radius: 10px; background: #1c1c1e; color: #ff6b6b; font-size: 14px; transition: transform 140ms var(--ease-out); }
#hist .det .ddel:active { transform: scale(0.97); }

/* libro mayor */
#hist .mon { position: sticky; top: 0; z-index: 3; background: var(--bg); padding: 10px 0 8px; border-bottom: 1px solid var(--line); }
#hist .mon > button { display: flex; width: 100%; align-items: baseline; justify-content: space-between; min-height: 44px; text-align: left; }
#hist .mon .n { font-size: 17px; font-weight: 600; text-transform: capitalize; display: flex; align-items: center; gap: 8px; }
#hist .mon .n svg { width: 12px; height: 12px; fill: none; stroke: var(--ink-2); stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; transition: transform 200ms var(--ease-out); }
#hist .mon[data-open="false"] .n svg { transform: rotate(-90deg); }
#hist .mon .t { font-size: 17px; }
#hist .mon .s { display: flex; justify-content: space-between; font-size: 13px; color: var(--ink-2); margin-top: 2px; }
#hist .mon .mbar { height: 2px; margin-top: 8px; background: var(--ink); }
#hist .rows { display: grid; grid-template-rows: 1fr; transition: grid-template-rows 260ms var(--ease-out); }
#hist .rows[data-open="false"] { grid-template-rows: 0fr; }
#hist .rows > ul { overflow: hidden; min-height: 0; }
#hist .rw { border-bottom: 1px solid var(--line); }
#hist .rwb { display: grid; grid-template-columns: 44px 1fr auto; align-items: center; width: 100%; min-height: 60px; padding: 8px 0 4px; text-align: left; transition: background-color 140ms ease; }
#hist .rwb:active { background: #0d0d0d; }
#hist .rwb .d { font-size: 14px; color: var(--ink-2); }
#hist .rwb b { display: block; font-size: 17px; font-weight: 500; }
#hist .rwb i { display: block; margin-top: 2px; font-size: 13px; font-style: normal; color: var(--ink-2); }
#hist .rwb .c { font-size: 17px; text-align: right; }
#hist .rbar { height: 3px; margin: 2px 0 8px 44px; display: flex; }
#hist .exp { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 240ms var(--ease-out); }
#hist .rw.open .exp { grid-template-rows: 1fr; }
#hist .exp > div { overflow: hidden; min-height: 0; padding-left: 44px; }

/* calendario */
#hist .mhead { display: flex; align-items: center; justify-content: space-between; margin-top: 6px; }
#hist .mhead h3 { font-size: 20px; font-weight: 600; text-transform: capitalize; }
#hist .mhead div { display: flex; }
#hist .mnav { width: 44px; height: 44px; display: grid; place-items: center; color: var(--ink-2); border-radius: 50%; transition: transform 140ms var(--ease-out); }
#hist .mnav:active { transform: scale(0.92); }
#hist .mnav svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
#hist .wk, #hist .cgrid { display: grid; grid-template-columns: repeat(7, 1fr); }
#hist .wk { margin-top: 8px; font-size: 12px; color: var(--ink-2); text-align: center; }
#hist .cgrid { margin-top: 2px; }
#hist .gridwrap.slide { animation: hslide 240ms var(--ease-out); }
#hist .gridwrap.slide.back { animation-name: hslideb; }
@keyframes hslide { from { transform: translateX(18px); opacity: 0; } }
@keyframes hslideb { from { transform: translateX(-18px); opacity: 0; } }
#hist .day { position: relative; height: 62px; padding: 6px 0 0; border-radius: 10px; display: flex; flex-direction: column; align-items: center; transition: background-color 140ms ease; }
#hist .day:active { background: #101010; }
#hist .day .dn { font-size: 12px; color: var(--ink-2); line-height: 1; }
#hist .day.today .dn { color: var(--ink); font-weight: 600; }
#hist .day.today .dn::after { content: ""; display: block; height: 2px; margin: 3px auto 0; width: 12px; background: var(--ink); }
#hist .day .dbars { position: absolute; left: 0; right: 0; bottom: 6px; display: flex; justify-content: center; align-items: flex-end; gap: 3px; height: 38px; }
#hist .day .dbars > span { display: flex; width: 12px; }
#hist .day[aria-pressed="true"] { background: var(--sheet); box-shadow: inset 0 0 0 1px #3a3a3c; }
#hist .cal-det { flex: 1; min-height: 0; margin-top: 10px; border-top: 1px solid var(--line); overflow-y: auto; padding: 14px 20px calc(var(--safe-bottom) + 20px); }
#hist .cal-det::-webkit-scrollbar { display: none; }
#hist .cal-det h4 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
#hist .cal-det .none { margin-top: 6px; font-size: 14px; color: var(--ink-2); }
#hist .cd { padding: 10px 0; border-bottom: 1px solid var(--line); }
#hist .cd:last-child { border: 0; }
#hist .cd .top { display: flex; justify-content: space-between; align-items: baseline; font-size: 17px; }
#hist .cd .top b { font-weight: 500; }
#hist .cd .l2 { margin-top: 2px; font-size: 13px; color: var(--ink-2); }

/* ================= Historial: libro mayor por fecha + calendario ================= */
const DOW = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const H = { view: 'mayor', f: 'all', closed: new Set(), sel: null, y: null, m: null, day: undefined, dir: 0, lastF: 'all' };
const hTime = (c) => new Date(c.startAt);
const chev = '<svg width="12" height="12" viewBox="0 0 12 12"><path d="M2 4l4 4 4-4"/></svg>';

/** Barra de franjas de una carga en Casa (Valle / Llano / Punta); contorno para las públicas, que no tienen franja. */
function stackH(c) {
  if (c.location === 'public') return '<div class="outl"></div>';
  const t = c.valleKwh + c.llanoKwh + c.puntaKwh || 1;
  return `<div class="stackh">${[['v1', c.valleKwh], ['v2', c.llanoKwh], ['v3', c.puntaKwh]].map(([k, v]) => `<i class="${k}" style="flex:${v / t}"></i>`).join('')}</div>`;
}
const hWhere = (c) => (c.location === 'home' ? `Casa · Valle ${Math.round((c.valleKwh / c.kwh) * 100)}%` : esc(c.network || 'Pública'));
const hPct = (c) => (c.startPct != null ? ` · ${pctTxt(c.startPct)}→${pctTxt(c.endPct)}%` : '');
function hDetail(c) {
  const d = hTime(c), kv = (l, v, em = '') => `<div class="dk"><span>${l}</span><b>${v}${em ? `<em>${em}</em>` : ''}</b></div>`;
  let h = '<div class="det">';
  if (c.location === 'home') {
    const e = new Date(c.endAt), p = (k) => Math.round((c[k + 'Kwh'] / c.kwh) * 100);
    h += kv('Horario', `${hhmm(d)} → ${hhmm(e)}`, fmtDur((e - d) / 60000)) + `<div class="dbar">${stackH(c)}</div>` + kv('Franjas', `Valle ${p('valle')}%`, `Llano ${p('llano')}% · Punta ${p('punta')}%`);
  } else h += kv('Red', esc(c.network || 'Pública')) + kv('Precio', `${money2(c.pricePerKwh)}/kWh`, c.fixedFee > 0 ? `+ ${money(c.fixedFee)} fijo` : '');
  if (c.startPct != null) h += kv('Batería', `${pctTxt(c.startPct)} → ${pctTxt(c.endPct)}%`);
  h += kv('Odómetro', c.odometerKm != null ? `${int(c.odometerKm)} km` : '—') + kv('Costo por kWh', money2(c.cost / c.kwh));
  return h + `<button class="ddel" data-del="${c.id}">Eliminar esta carga</button></div>`;
}
const hLegend = '<div class="legend"><span class="l1">Valle</span><span class="l2">Llano</span><span class="l3">Punta</span><span class="l4">Pública</span></div>';
const hTabs = () => `<div class="htabs" role="group" aria-label="Filtrar">${[['all', 'Todas'], ['home', 'Casa'], ['public', 'Pública']].map(([k, l]) => `<button data-f="${k}" aria-pressed="${H.f === k}">${l}</button>`).join('')}</div>`;
const hList = () => S.charges.filter((c) => H.f === 'all' || c.location === H.f);
const hSummary = (list) => `<p class="hsub"><b>${money(list.reduce((a, c) => a + c.cost, 0))}</b> · ${int(list.reduce((a, c) => a + c.kwh, 0))} kWh · ${list.length} ${list.length === 1 ? 'carga' : 'cargas'}</p>`;

/* ----- Libro mayor: meses con su total y barras comparables, cada carga se despliega en el lugar ----- */
function mayorHtml() {
  const all = [...S.charges], maxCost = Math.max(...all.map((c) => c.cost), 1), list = hList();
  const groups = new Map();
  [...list].sort((a, b) => hTime(b) - hTime(a)).forEach((c) => { const k = `${hTime(c).getFullYear()}-${hTime(c).getMonth()}`; if (!groups.has(k)) groups.set(k, []); groups.get(k).push(c); });
  const totals = [...groups.values()].map((g) => g.reduce((a, c) => a + c.cost, 0)), maxT = Math.max(...totals, 1);
  const rowHtml = (c) => `<li class="rw${H.sel === c.id ? ' open' : ''}" data-id="${c.id}"><button class="rwb" aria-expanded="${H.sel === c.id}"><span class="d">${shortDate(hTime(c))}</span><span><b>${kwhTxt(c.kwh)} kWh</b><i>${hWhere(c)}${hPct(c)}</i></span><span class="c">${money(c.cost)}</span></button>`
    + `<div class="rbar"><div style="width:${Math.max(1.5, (c.cost / maxCost) * 100)}%;height:100%">${stackH(c)}</div></div><div class="exp"><div>${H.sel === c.id ? hDetail(c) : ''}</div></div></li>`;
  const body = [...groups].map(([k, g], i) => {
    const open = !H.closed.has(k), t = totals[i], kwh = g.reduce((a, c) => a + c.kwh, 0), m = hTime(g[0]);
    return `<section class="mon" data-open="${open}" data-k="${k}"><button data-m="${k}" aria-expanded="${open}"><span class="n">${chev}${MONTHS[m.getMonth()]}</span><span class="t">${money(t)}</span></button><div class="s"><span>${g.length} ${g.length === 1 ? 'carga' : 'cargas'} · ${int(kwh)} kWh</span><span>${money2(t / kwh)}/kWh</span></div><div class="mbar" style="width:${(t / maxT) * 100}%"></div></section>`
      + `<div class="rows" data-open="${open}" data-k="${k}"><ul>${g.map(rowHtml).join('')}</ul></div>`;
  }).join('');
  return `<div class="hh">${hSummary(list)}${hTabs()}</div><div class="hscroll" id="hscroll">${body || '<p class="note">No hay cargas para mostrar.</p>'}${hLegend}</div>`;
}

/* ----- Calendario: cada día es una barra de energía apilada por franja ----- */
function calHtml() {
  const list = hList();
  if (H.y == null) { const last = [...S.charges].sort((a, b) => hTime(b) - hTime(a))[0], d = last ? hTime(last) : new Date(); H.y = d.getFullYear(); H.m = d.getMonth(); }
  const first = new Date(H.y, H.m, 1), lead = (first.getDay() + 6) % 7, days = new Date(H.y, H.m + 1, 0).getDate(), now = new Date();
  const inMonth = list.filter((c) => hTime(c).getFullYear() === H.y && hTime(c).getMonth() === H.m);
  const byDay = new Map(); inMonth.forEach((c) => { const d = hTime(c).getDate(); if (!byDay.has(d)) byDay.set(d, []); byDay.get(d).push(c); });
  // al cambiar de mes (o filtro) se elige solo el último día con cargas; un toque en un día vacío se respeta
  if (H.day === undefined || (H.day != null && H.f !== H.lastF)) H.day = byDay.size ? Math.max(...byDay.keys()) : null;
  H.lastF = H.f; calCache = { byDay };
  const maxKwh = Math.max(...S.charges.map((c) => c.kwh), 1), cells = [];
  for (let i = 0; i < Math.ceil((lead + days) / 7) * 7; i++) {
    const d = i - lead + 1;
    if (d < 1 || d > days) { cells.push('<span></span>'); continue; }
    const cs = byDay.get(d) || [], isToday = H.y === now.getFullYear() && H.m === now.getMonth() && d === now.getDate();
    const bars = cs.map((c) => {
      const h = Math.max(4, (c.kwh / maxKwh) * 38);
      if (c.location === 'public') return `<span style="height:${h}px"><div class="outl"></div></span>`;
      const t = c.valleKwh + c.llanoKwh + c.puntaKwh;
      return `<span style="height:${h}px"><span class="stackv">${[['v1', c.valleKwh], ['v2', c.llanoKwh], ['v3', c.puntaKwh]].filter(([, v]) => v / t > 0.001).map(([k, v]) => `<i class="${k}" style="flex:${v / t}"></i>`).join('')}</span></span>`;
    }).join('');
    const lbl = `${d} de ${MONTHS[H.m]}${cs.length ? `, ${cs.length} ${cs.length === 1 ? 'carga' : 'cargas'}, ${kwhTxt(cs.reduce((a, c) => a + c.kwh, 0))} kWh` : ', sin cargas'}`;
    cells.push(`<button class="day${isToday ? ' today' : ''}" data-d="${d}" aria-label="${lbl}" aria-pressed="${H.day === d}"><span class="dn">${d}</span><span class="dbars">${bars}</span></button>`);
  }
  const nav = (k, p) => `<button class="mnav" data-nav="${k}" aria-label="${k < 0 ? 'Mes anterior' : 'Mes siguiente'}"><svg width="20" height="20" viewBox="0 0 20 20"><path d="${p}"/></svg></button>`;
  const anim = H.dir ? ` slide${H.dir < 0 ? ' back' : ''}` : '';
  H.dir = 0;
  return `<div class="hh">${hSummary(inMonth)}${hTabs()}<div class="mhead"><h3>${MONTHS[H.m]} ${H.y}</h3><div>${nav(-1, 'M12 4l-6 6 6 6')}${nav(1, 'M8 4l6 6-6 6')}</div></div>`
    + `<div class="wk">${['L', 'M', 'M', 'J', 'V', 'S', 'D'].map((x) => `<span>${x}</span>`).join('')}</div><div class="gridwrap${anim}"><div class="cgrid">${cells.join('')}</div></div>${hLegend}</div><div class="cal-det" id="caldet">${calDetail()}</div>`;
}
let calCache = { byDay: new Map() };
function calDetail() {
  if (H.day == null) return '<p class="none">Tocá un día para ver sus cargas.</p>';
  const d = new Date(H.y, H.m, H.day), cs = calCache.byDay.get(H.day) || [];
  return `<h4>${cap(DOW[d.getDay()])} ${d.getDate()} de ${MONTHS[d.getMonth()]}</h4>`
    + (cs.map((c) => `<div class="cd"><div class="top"><b>${kwhTxt(c.kwh)} kWh</b><span>${money(c.cost)}</span></div><div class="l2">${hWhere(c)}${hPct(c)}</div>${hDetail(c)}</div>`).join('') || '<p class="none">Sin cargas ese día.</p>');
}

function renderList() {
  document.querySelectorAll('#hView button').forEach((b) => b.setAttribute('aria-pressed', b.dataset.view === H.view));
  $('#hist').innerHTML = H.view === 'mayor' ? mayorHtml() : calHtml();
}
const calGo = (k) => { const d = new Date(H.y, H.m + k, 1); H.y = d.getFullYear(); H.m = d.getMonth(); H.day = undefined; H.dir = k; renderList(); };
$('#hView').addEventListener('click', (e) => { const b = e.target.closest('[data-view]'); if (b && b.dataset.view !== H.view) { H.view = b.dataset.view; renderList(); } });
$('#hist').addEventListener('click', (e) => {
