/* ---------- Abrir y cerrar pantallas (pila) ---------- */
const stack = [];
function openFn(id) {
  if (id === 'cargar') initCargar();
  if (id === 'prog') initProg();
  renderAll();
  const el = $('#fn-' + id);
  el.inert = false; el.classList.add('open');
  (stack[stack.length - 1] ? $('#fn-' + stack[stack.length - 1]) : $('#home')).inert = true;
  stack.push(id);
  if (id === 'prog') renderProg();
  if (id === 'activa') { confirmShown = false; renderActiva(); }
  if (id === 'cargar') renderCargar();
}
function closeFn() {
  const id = stack.pop(); if (!id) return;
  const el = $('#fn-' + id);
  el.classList.remove('open'); el.inert = true;
  (stack[stack.length - 1] ? $('#fn-' + stack[stack.length - 1]) : $('#home')).inert = false;
}
document.querySelectorAll('[data-close]').forEach((b) => b.addEventListener('click', closeFn));
addEventListener('keydown', (e) => { if (e.key === 'Escape') closeFn(); });

