964	  /* ----- Carga en curso: en espera, cargando, a confirmar ----- */
965	  let confirmAt = null, confirmShown = false, confirmEnd = null;
966	  function activeInfo(now) {
967	    const a = S.active, B = S.vehicle.batteryKwh, kw = nominalKw(), calib = calibration().factor;
968	    const start = new Date(a.startAt), stop = new Date(a.stopAt);
969	    const st = confirmAt ? 'ended' : now < start ? 'waiting' : now < stop ? 'charging' : 'ended';
970	    const est = (to) => L.estimateAtTime(a.startPct, start, to, kw, B, calib);
971	    const cost = (kwh, to) => (kwh > 0.01 && to > start ? L.computeHomeChargeCost(start, to, kwh, S.rates, S.puntaStart, { nominalKw: kw, calibration: calib, startPct: a.startPct, batteryKwh: B }) : null);
972	    return { a, st, start, stop, B, kw, calib, est, cost };
