979	    bar.hidden = false; bar.classList.toggle('live', I.st === 'charging');
980	    if (I.st === 'waiting') bar.textContent = `Programada · arranca en ${fmtDur((I.start - now) / 60000)}`;
981	    else if (I.st === 'charging') bar.textContent = `Cargando · ≈ ${pctTxt(I.est(now).pct)}% · corta ${hhmm(I.stop)}`;
