const renderCargar = () => regWiz.render();

/* ================= Borrador: retomar un asistente interrumpido ================= */
const DRAFT_KEY = 'carga.v3.borrador', DRAFT_TTL = 48 * 36e5; // un borrador de más de 2 días ya no sirve
const DRAFTS = { cargar: { label: 'Registrar carga', state: () => R, wiz: () => regWiz }, prog: { label: 'Programar carga', state: () => W, wiz: () => progWiz } };
function loadDraft() {
  try { const d = JSON.parse(localStorage.getItem(DRAFT_KEY)); if (d && DRAFTS[d.id] && Date.now() - d.at < DRAFT_TTL) return d; } catch (_) {}
  return null;
}
function saveDraft(id, step) { try { localStorage.setItem(DRAFT_KEY, JSON.stringify({ id, step, at: Date.now(), state: DRAFTS[id].state() })); } catch (_) {} }
function clearDraft() { try { localStorage.removeItem(DRAFT_KEY); } catch (_) {} renderDraft(); }
const agoTxt = (t) => { const m = Math.max(0, Math.round((Date.now() - t) / 60000)); return m < 1 ? 'hace un momento' : m < 60 ? `hace ${m} min` : `hace ${Math.round(m / 60)} h`; };
let draftShown = '';
function renderDraft() {
  const el = $('#draftBar'), d = loadDraft();
  if (!d) { el.hidden = true; el.innerHTML = ''; draftShown = ''; return; }
  const html = `<p>Borrador sin guardar</p><p class="ds">${DRAFTS[d.id].label} · ${agoTxt(d.at)}</p><div class="da"><button data-draft="resume">Continuar</button><button data-draft="discard">Eliminar</button></div>`;
  if (html !== draftShown) { el.innerHTML = html; draftShown = html; }
  el.hidden = false;
}
function resumeDraft() {
  const d = loadDraft(); if (!d) return;
  Object.assign(DRAFTS[d.id].state(), d.state); // los valores vuelven tal cual, el asistente retoma en el mismo paso
  openFn(d.id, d.step);
}
$('#draftBar').addEventListener('click', (e) => {
  const b = e.target.closest('[data-draft]'); if (!b) return;
  if (b.dataset.draft === 'resume') resumeDraft(); else if (confirm('¿Eliminar el borrador?')) clearDraft();
});
// si la app se cierra o pasa a segundo plano a mitad de un asistente, el borrador se guarda al instante
const flushDrafts = () => Object.values(DRAFTS).forEach((x) => x.wiz().flush());
addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') flushDrafts(); });
addEventListener('pagehide', flushDrafts);

