const c=window.__carga; const q=(s)=>document.querySelector(s); const wait=(ms)=>new Promise(r=>setTimeout(r,ms)); const a={}; window.confirm=()=>true;
const P=(s)=>q('#fn-prog '+s); const key=()=>localStorage.getItem('carga.v3.borrador'); const tap=async(b)=>{b.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerType:'touch'})); b.dispatchEvent(new PointerEvent('pointerup',{bubbles:true})); await wait(40)};
// (1) Programar: cambiar la batería (paso 0) → borrador
