/**
 * Dial del odómetro. Con un odómetro anterior, la regla arranca ahí y avanza hasta 1.500 km (marcas cada km,
 * números cada 50): el odómetro nuevo siempre es mayor. Sin uno anterior no hay desde dónde medir y queda el ajuste fino.
 */
const odoCfg = (W) => {
  const last = lastOdo();
  return { kind: 'num', noRuler: last == null, aria: 'Odómetro', get: () => W.odo, set: (v) => { W.odo = Math.max(last || 0, Math.round(v)); }, seed: last || 0,
    label: () => (W.odo == null ? 'Omitir' : int(W.odo)), nudges: [[-10, '−10'], [-1, '−1'], [1, '+1'], [10, '+10']],
    base: last || 0, min: 0, max: 1500, step: 1, ppv: 5, major: 10, every: 50, tick: (n) => int((last || 0) + n) };
};

