#hist .legend span::before { content: ""; display: inline-block; width: 8px; height: 8px; margin-right: 6px; vertical-align: -0.5px; }
#hist .legend .l1::before { background: var(--valle); } #hist .legend .l2::before { background: var(--llano); } #hist .legend .l3::before { background: var(--punta); } #hist .legend .l4::before { box-shadow: inset 0 0 0 1.5px var(--llano); }
#hist .stackh { display: flex; gap: 1px; height: 100%; width: 100%; }
#hist .stackh i, #hist .stackv i { display: block; min-width: 1px; }
#hist .stackv { display: flex; flex-direction: column-reverse; gap: 1px; width: 100%; height: 100%; }
#hist .stackv i { min-height: 1px; }
#hist .v1 { background: var(--valle); } #hist .v2 { background: var(--llano); } #hist .v3 { background: var(--punta); }
#hist .outl { width: 100%; height: 100%; box-shadow: inset 0 0 0 1.5px var(--llano); }

