378	
379	  /** "2026-07-15 21:30:00" (SQLite, en UTC) o una fecha ISO → ISO; null si no es una fecha. */
380	  function toIso(s) {
381	    if (!s) return null;
382	    const t = String(s), d = new Date(/Z|[+-]dd:?dd$/.test(t) ? t : t.replace(' ', 'T') + 'Z');
383	    return isNaN(d) ? null : d.toISOString();
384	  }
385	  const numOrNull = (v) => (v == null || v === '' || !isFinite(Number(v)) ? null : Number(v));
386	  const posOrZero = (v) => (isFinite(Number(v)) && Number(v) > 0 ? Number(v) : 0);
387	
388	  /** Una carga de cualquier respaldo → el formato de esta app, o null si le faltan datos esenciales. */
389	  function normalizeCharge(c) {
390	    if (!c || typeof c !== 'object') return null;
391	    const location = c.location === 'home' || c.location === 'public' ? c.location : null;
392	    const startAt = toIso(c.startAt) || toIso(c.createdAt); // las públicas viejas pueden no tener fecha de inicio
393	    const kwh = Number(c.kwh), cost = Number(c.cost);
394	    if (!location || !startAt || !(kwh > 0) || !isFinite(cost) || cost < 0) return null;
395	    return {
396	      location, startAt, endAt: toIso(c.endAt) || (location === 'home' ? startAt : null), kwh,
397	      odometerKm: numOrNull(c.odometerKm), pricePerKwh: numOrNull(c.pricePerKwh), fixedFee: numOrNull(c.fixedFee),
398	      network: c.network ? String(c.network) : null, cost,
399	      valleKwh: posOrZero(c.valleKwh), llanoKwh: posOrZero(c.llanoKwh), puntaKwh: posOrZero(c.puntaKwh),
400	      startPct: numOrNull(c.startPct), endPct: numOrNull(c.endPct),
401	    };
402	  }
403	
404	  /**
405	   * Lee un respaldo de la app vieja (carga-ev, versión 1) o de esta, y se queda solo con lo que sirve:
406	   * cargas, vehículo, tarifas, franja Punta y cargador. No trae tema, colores, notificaciones, ubicación ni borradores.
407	   */
408	  function parseBackup(data) {
409	    if (!data || typeof data !== 'object' || !Array.isArray(data.charges)) throw new Error('El archivo no parece un respaldo de Carga.');
410	    const own = data.app === 'carga', s = own ? data : data.settings || {};
411	    const charges = []; let skipped = 0;
412	    for (const c of data.charges) { const n = normalizeCharge(c); if (n) charges.push(n); else skipped++; }
413	    charges.sort((a, b) => a.startAt.localeCompare(b.startAt));
414	    const v = data.vehicle, vehicle = v && Number(v.batteryKwh) > 0 && Number(v.consumptionWhKm) > 0
415	      ? { name: String(v.name || 'Mi auto'), batteryKwh: Number(v.batteryKwh), consumptionWhKm: Number(v.consumptionWhKm) } : null;
416	    const r = own ? data.rates : { valle: s.tariffValle, llano: s.tariffLlano, punta: s.tariffPunta };
417	    const rates = r && [r.valle, r.llano, r.punta].every((x) => Number(x) > 0) ? { valle: Number(r.valle), llano: Number(r.llano), punta: Number(r.punta) } : null;
418	    const ps = Number(own ? data.puntaStart : s.puntaStartHour), amps = Number(own ? data.amps : s.homeChargerAmps), volts = Number(own ? data.volts : s.homeChargerVolts);
419	    return {
420	      kind: own ? 'carga' : 'carga-ev', exportedAt: toIso(data.exportedAt), charges, skipped, vehicle, rates,
421	      puntaStart: PUNTA_START_OPTIONS.includes(ps) ? ps : null, charger: amps > 0 && volts > 0 ? { amps, volts } : null,
422	      chips: own && data.chips && typeof data.chips === 'object' ? data.chips : null,
423	      ignored: own ? [] : ['tema y colores', 'personalización visual', 'notificaciones', 'ubicación de casa', 'carga en curso y borradores'],
424	    };
425	  }
426	
427	  const chargeKey = (c) => ;
428	
429	  /**
430	   * Suma cargas importadas a las existentes sin duplicar (misma hora, kWh y lugar) o las reemplaza.
431	   * Los datos de ejemplo () siempre se quitan: al importar datos reales ya no hacen falta.
432	   */
433	  function mergeCharges(existing, incoming, mode) {
434	    const samples = existing.filter((c) => c.sample).length;
435	    const out = mode === 'replace' ? [] : existing.filter((c) => !c.sample);
436	    const seen = new Set(out.map(chargeKey));
437	    let id = Math.max(Date.now(), ...existing.map((c) => c.id + 1)), added = 0, duplicates = 0;
438	    for (const c of incoming) {
439	      const k = chargeKey(c);
440	      if (seen.has(k)) { duplicates++; continue; }
441	      seen.add(k); out.push({ ...c, id: id++ }); added++;
442	    }
443	    return { charges: out, added, duplicates, removedSamples: samples };
444	  }
