333	  const int = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
334	  const dec = (n, d = 1) => Number(n).toFixed(d).replace('.', ',');
335	  /** Número con coma decimal: entre `min` y `max` decimales (sin ceros de más). */
336	  function fmtNum(n, min, max) {
337	    const k = 10 ** max;
338	    const [i, f0 = ''] = (Math.round(n * k) / k).toFixed(max).split('.');
339	    let f = f0.replace(/0+$/, '');
340	    while (f.length < min) f += '0';
341	    return f ? `${i},${f}` : i;
342	  }
343	  const kwhTxt = (n) => fmtNum(n, 1, 2); // el cargador muestra hasta 2 decimales
344	  const pctTxt = (n) => fmtNum(n, 0, 1); // el % de batería, hasta 1 decimal
345	  const money = (n) => '$ ' + int(n);

