const money = (n) => '$ ' + int(n);
const money2 = (n) => '$ ' + dec(n, 2);
const hhmm = (d) => `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
const shortDate = (d) => `${d.getDate()} ${MONTHS[d.getMonth()].slice(0, 3)}`;
const cap = (s) => s[0].toUpperCase() + s.slice(1);
const toInput = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}T${hhmm(d)}`;
const num = (v) => parseFloat(String(v).replace(',', '.'));

/* ---------- Estado y persistencia ---------- */
const KEY = 'carga.v3';
const DEFAULTS = () => ({
  vehicle: { name: 'GAC Aion UT Max', batteryKwh: 60, consumptionWhKm: 135 },
  rates: { ...L.UTE_2026_RATES }, puntaStart: L.DEFAULT_PUNTA_START, amps: 24, volts: 226, charges: [],
});

let S;
try { S = JSON.parse(localStorage.getItem(KEY)); } catch (_) {}
if (!S || !Array.isArray(S.charges)) { S = DEFAULTS(); S.charges = L.makeSeed(new Date()); }
const persist = () => { try { localStorage.setItem(KEY, JSON.stringify(S)); } catch (_) {} };

const nominalKw = () => (S.amps > 0 && S.volts > 0 ? L.chargerKw(S.amps, S.volts) : 0);
const homeCharges = () => S.charges.filter((c) => c.location === 'home');
const calibration = () => L.computeCalibration(homeCharges(), nominalKw(), S.vehicle.batteryKwh);
const consumption = () => { const real = L.realConsumption(S.charges, S.vehicle.batteryKwh); return { real, rc: L.rangeConsumption(S.vehicle, real) }; };

/* ---------- Precios de redes públicas (en vivo → caché → resguardo) ---------- */
const NET_URL = 'https://evuruguay.com/cargadores_all.csv', NET_KEY = 'carga.v3.redes';
let net = { rows: L.FALLBACK_NETWORK_ROWS, source: 'base', at: null };
async function loadNetworks() {
  try { const c = JSON.parse(localStorage.getItem(NET_KEY)); if (c && c.rows && c.rows.length) net = { rows: c.rows, source: 'guardado', at: c.at }; } catch (_) {}
  try {
    const ctl = new AbortController(), t = setTimeout(() => ctl.abort(), 4000);
    const res = await fetch(NET_URL, { signal: ctl.signal, cache: 'no-store' });
    clearTimeout(t);
    if (!res.ok) throw new Error(res.status);
    const rows = L.parseCsv(await res.text());
    if (!rows.length) throw new Error('vacío');
    net = { rows, source: 'en vivo', at: Date.now() };
    try { localStorage.setItem(NET_KEY, JSON.stringify({ rows, at: net.at })); } catch (_) {}
  } catch (_) { /* sin red: se queda con caché o resguardo */ }
  renderAll();
}
const groups = () => L.groupNetworkRows(net.rows);

/* ---------- Fichas: carril con zoom central ---------- */
const SLOT = 100, CHIP_D = 126, CHIP_GAP = 16; // paso del carril, diámetro de la ficha activa, espacio fijo entre bordes
function makeRail(el, { count, html, label, onChange, onActivate }) {
  el.innerHTML = Array.from({ length: count }, (_, i) => `<button class="slot" data-i="${i}" aria-label="${label(i)}"><span class="c">${html(i)}</span></button>`).join('');
  const slots = [...el.children], discs = slots.map((s) => s.firstElementChild);
  let idx = -1, prog = false, timer = 0, raf = 0, md = null, dragged = false;
  const at = () => Math.max(0, Math.min(count - 1, Math.round(el.scrollLeft / SLOT)));
  /**
   * Cada ficha se acomoda por sus bordes, no por sus centros: con tamaños distintos, centros parejos dejan
   * espacios desiguales (casi nada junto a la grande, mucho entre las chicas). Se suman los diámetros reales
   * más un espacio fijo, y el punto que corresponde a la posición del carril queda justo bajo la flecha.
   */
  function paint() {
    const p = el.scrollLeft / SLOT, ds = [], ks = [];
    for (let i = 0; i < count; i++) {
      const k = Math.max(0, 1 - Math.abs(i - p));
      ks.push(k); ds.push(CHIP_D * (0.52 + 0.48 * (k * k * (3 - 2 * k))));
    }
    const cs = []; let x = 0;
    for (let i = 0; i < count; i++) { cs.push(x + ds[i] / 2); x += ds[i] + CHIP_GAP; }
    const lo = Math.max(0, Math.min(count - 1, Math.floor(p))), hi = Math.min(count - 1, lo + 1);
    const pos = cs[lo] + (cs[hi] - cs[lo]) * Math.min(1, Math.max(0, p - lo));
    for (let i = 0; i < count; i++) {
      // desplazamiento = dónde debe estar la ficha − dónde la deja el carril (100 px entre centros)
      discs[i].style.transform = `translateX(${(cs[i] - pos - (i - p) * SLOT).toFixed(2)}px) scale(${(ds[i] / CHIP_D).toFixed(3)})`;
      discs[i].style.setProperty('--k', ks[i].toFixed(3));
      slots[i].style.zIndex = Math.round(ks[i] * 10);
    }
    const n = at();
    if (n !== idx) { idx = n; onChange(n, !prog); }
  }
  const onScroll = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(paint); };
  const onClick = (e) => {
    if (dragged) return;
    const s = e.target.closest('.slot'); if (!s) return;
    const i = +s.dataset.i;
    if (i === at()) onActivate(i); else go(i, true, true);
  };
  const onKey = (e) => {
    if (e.key === 'ArrowRight' && at() < count - 1) go(at() + 1, true, true);
    if (e.key === 'ArrowLeft' && at() > 0) go(at() - 1, true, true);
  };
  // arrastre con mouse (solo vista previa de escritorio)
  const onDown = (e) => { if (e.pointerType === 'mouse') md = { x: e.clientX, l: el.scrollLeft, moved: false }; };
  const onMove = (e) => {
    if (!md) return;
    const dx = e.clientX - md.x;
    if (!md.moved && Math.abs(dx) > 5) { md.moved = true; el.classList.add('mouse-drag'); }
    if (md.moved) el.scrollLeft = md.l - dx;
  };
  const onUp = () => {
    if (!md) return;
    const m = md; md = null;
    if (!m.moved) return;
    el.classList.remove('mouse-drag');
    dragged = true; setTimeout(() => (dragged = false), 0);
    el.scrollTo({ left: Math.round(el.scrollLeft / SLOT) * SLOT, behavior: 'smooth' });
  };
  el.addEventListener('scroll', onScroll, { passive: true });
  el.addEventListener('click', onClick);
  el.addEventListener('keydown', onKey);
  el.addEventListener('pointerdown', onDown);
  addEventListener('pointermove', onMove);
  addEventListener('pointerup', onUp);
  /** Quita todos los escuchadores: hay que llamarlo antes de reconstruir la bandeja sobre el mismo elemento. */
  function destroy() {
    cancelAnimationFrame(raf); clearTimeout(timer);
    el.removeEventListener('scroll', onScroll); el.removeEventListener('click', onClick);
    el.removeEventListener('keydown', onKey); el.removeEventListener('pointerdown', onDown);
    removeEventListener('pointermove', onMove); removeEventListener('pointerup', onUp);
  }
  /** `byUser`: el cambio de índice cuenta como acción del usuario (toque en una ficha lateral). */
  function go(i, smooth, byUser) {
    prog = !byUser; clearTimeout(timer);
    timer = setTimeout(() => (prog = false), smooth ? 700 : 80);
    el.scrollTo({ left: i * SLOT, behavior: smooth ? 'smooth' : 'instant' });
  }
  return { go, paint, destroy, get index() { return at(); }, relabel(fn) { discs.forEach((c, i) => (c.firstElementChild.textContent = fn(i))); } };
}

const ICONS = {
