  precios: '<path d="M4 12.5V5h7.5L20 13.5 13.5 20 4 12.5z"/><circle cx="8.2" cy="9.2" r="1.2"/>',
};
const FUNCS = [
  { id: 'cargar', name: 'Registrar carga', head: ['Registrar', 'carga'] },
  { id: 'prog', name: 'Programar carga', head: ['Programar', 'carga'] },
