    }
    const from = new Date(now.getTime() - 30 * DAY), prev = L.statsBetween(S.charges, new Date(now.getTime() - 60 * DAY), from).total;
    const cur = L.statsBetween(S.charges, from, end).total;
    return { from, end, cmp: { cur, prev, deltaPct: prev > 0 ? ((cur - prev) / prev) * 100 : null }, vs: 'los 30 días anteriores' };
  }

  function renderGasto() {
    const now = new Date(), p = period(now), cmp = p.cmp;
    const s = L.statsBetween(S.charges, p.from, p.end);
    const m6 = L.monthlyTotals(S.charges, now, 6), mx = Math.max(...m6.map((x) => x.total), 1);
    const saved = S.charges.filter((c) => new Date(c.startAt) >= p.from).reduce((a, c) => a + (c.location === 'home' ? L.valleSavings(c, S.rates) : 0), 0);
    const pct = (a, b) => (b > 0 ? Math.round((a / b) * 100) : 0);
    let h = `<div class="seg wide" role="group" aria-label="Período"><button data-gp="30d" aria-pressed="${gPeriod === '30d'}">30 días</button><button data-gp="mes" aria-pressed="${gPeriod === 'mes'}">Este mes</button></div>`;
    h += `<div class="hero2"><p class="big"><span class="cur">$</span>${int(s.total)}</p><p class="sub">${int(s.kwh)} kWh · ${s.count} ${s.count === 1 ? 'carga' : 'cargas'}</p>`;
    if (cmp.deltaPct != null) h += `<p class="find">${cmp.deltaPct >= 0 ? '↑' : '↓'} ${Math.abs(Math.round(cmp.deltaPct))}% frente a ${p.vs} (${money(cmp.prev)}).</p>`;
    h += `</div>`;
    h += `<h3>Costos</h3><div class="kv"><span>Promedio por kWh</span><b>${s.kwh > 0 ? money2(s.avgPerKwh) : '—'}</b></div>`;
    h += `<div class="kv"><span>Costo por km<em>${s.costPerKm != null ? 'según tu odómetro' : 'cargá el odómetro en 2 cargas'}</em></span><b>${s.costPerKm != null ? money2(s.costPerKm) : '—'}</b></div>`;
    h += `<h3>Casa y pública</h3><div class="kv"><span>Casa<em>${int(s.homeKwh)} kWh · ${pct(s.homeKwh, s.kwh)}% de la energía</em></span><b>${money(s.homeCost)}</b></div>`;
    h += `<div class="kv"><span>Pública<em>${int(s.publicKwh)} kWh · ${pct(s.publicKwh, s.kwh)}% de la energía</em></span><b>${money(s.publicCost)}</b></div>`;
    h += `<h3>En Casa, por franja</h3>` + (s.homeKwh > 0 ? bands(s.vallePct, s.llanoPct, s.puntaPct) : '<p class="note">Sin cargas en casa este mes.</p>');
    if (saved > 1) h += `<p class="note">Cargando todo en Valle hubieras gastado ${money(saved)} menos en este período.</p>`;
    h += `<h3>Últimos 6 meses</h3><div class="bars">${m6.map((x, i) => `<div class="${i === 5 ? 'on' : ''}"><i style="height:${Math.round((x.total / mx) * 60)}px" title="${money(x.total)}"></i>${MONTHS[x.month].slice(0, 3)}</div>`).join('')}</div>`;
    $('#gasto').innerHTML = h;
  }

  $('#gasto').addEventListener('click', (e) => { const b = e.target.closest('[data-gp]'); if (b) { gPeriod = b.dataset.gp; $('#gTitle').textContent = gPeriod === 'mes' ? 'Este mes' : 'Últimos 30 días'; renderAll(); } });

  let autoPct = 80;
  function renderAuto() {
    const v = S.vehicle, { real, rc } = consumption();
    const src = { 'real-bateria': `medido en ${rc.samples} ${rc.samples === 1 ? 'tramo' : 'tramos'} (batería)`, 'real-pared': `medido en ${rc.samples} tramos (desde el enchufe)`, homologado: 'del fabricante; cargá odómetro y % para medirlo' }[rc.source];
    const km = L.rangeAtPct(v.batteryKwh, rc.whKm, autoPct), now = new Date(), s30 = L.statsBetween(S.charges, new Date(now.getTime() - 30 * 864e5), new Date(now.getTime() + 1));
    let h = `<div class="hero2"><p class="big">≈ ${km}<small>km</small></p><p class="sub">con la batería al <input class="inl" id="a-pct" inputmode="decimal" aria-label="Nivel de batería, en porcentaje" value="${pctTxt(autoPct)}">%</p><p class="find">${dec(L.whKmToKwh100(rc.whKm), 1)} kWh/100 km ${src}.</p>`;
    h += `<div class="seg wide" role="group" aria-label="Nivel de batería">${[20, 40, 60, 80, 100].map((p) => `<button data-ap="${p}" aria-pressed="${p === autoPct}">${p}%</button>`).join('')}</div></div>`;
    h += `<h3>Consumo</h3><div class="kv"><span>Real</span><b>${real && (real.batteryWhKm || real.wallWhKm) ? dec(L.whKmToKwh100(real.batteryWhKm || real.wallWhKm * L.ETA_AC), 1) + ' kWh/100 km' : '—'}</b></div>`;
    h += `<div class="kv"><span>Desde el enchufe<em>incluye pérdidas de carga</em></span><b>${real && real.wallWhKm ? dec(L.whKmToKwh100(real.wallWhKm), 1) + ' kWh/100 km' : '—'}</b></div>`;
    h += `<div class="kv"><span>Homologado</span><b>${dec(L.whKmToKwh100(v.consumptionWhKm), 1)} kWh/100 km</b></div>`;
    h += `<div class="kv"><span>Autonomía homologada</span><b>${L.autonomyKm(v.batteryKwh, v.consumptionWhKm)} km</b></div>`;
    h += `<h3>Mi auto y mi cargador</h3>`;
    h += `<div class="pair">${field('v-bat', 'Batería (kWh)', `<input id="v-bat" inputmode="decimal" value="${v.batteryKwh}">`)}${field('v-con', 'Consumo (Wh/km)', `<input id="v-con" inputmode="decimal" value="${v.consumptionWhKm}">`)}</div>`;
    h += `<div class="pair">${field('v-amp', 'Cargador (A)', `<input id="v-amp" inputmode="decimal" value="${S.amps}">`)}${field('v-volt', 'Tensión (V)', `<input id="v-volt" inputmode="decimal" value="${S.volts}">`)}</div>`;
    h += `<p class="note">${v.name} · cargador de casa ≈ ${dec(nominalKw(), 1)} kW. Costo de los últimos 30 días: ${s30.costPerKm != null ? money2(s30.costPerKm) + '/km' : 'sin datos de odómetro'}.</p>`;
    $('#auto').innerHTML = h;
  }
  $('#auto').addEventListener('click', (e) => { const b = e.target.closest('[data-ap]'); if (b) { autoPct = +b.dataset.ap; const y = $('#auto').scrollTop; renderAuto(); $('#auto').scrollTop = y; } });
  $('#auto').addEventListener('change', (e) => {
    const n = num(e.target.value); if (!(n > 0)) return;
    if (e.target.id === 'a-pct') { autoPct = Math.min(100, r1(n)); const y = $('#auto').scrollTop; renderAuto(); $('#auto').scrollTop = y; return; }
    ({ 'v-bat': () => (S.vehicle.batteryKwh = n), 'v-con': () => (S.vehicle.consumptionWhKm = n), 'v-amp': () => (S.amps = n), 'v-volt': () => (S.volts = n) }[e.target.id] || (() => {}))();
    persist(); const y = $('#auto').scrollTop; renderAll(); $('#auto').scrollTop = y;
  });

  function renderPrecios() {
    const r = S.rates, ps = S.puntaStart, now = new Date();
    let h = `<h3>UTE · Triple horaria residencial</h3>`;
    h += `<div class="pair">${field('r-valle', 'Valle $/kWh', `<input id="r-valle" inputmode="decimal" value="${String(r.valle).replace('.', ',')}">`, '00:00 a 07:00, todos los días')}${field('r-llano', 'Llano $/kWh', `<input id="r-llano" inputmode="decimal" value="${String(r.llano).replace('.', ',')}">`, 'el resto')}</div>`;
    h += field('r-punta', 'Punta $/kWh', `<input id="r-punta" inputmode="decimal" value="${String(r.punta).replace('.', ',')}">`, `${ps}:00 a ${ps + 4}:00, solo días hábiles`);
    h += `<div class="seg wide" role="group" aria-label="Inicio de la franja Punta">${L.PUNTA_START_OPTIONS.map((p) => `<button data-ps="${p}" aria-pressed="${p === ps}">Punta ${p}–${p + 4}</button>`).join('')}</div>`;
    h += `<p class="note">Pliego tarifario 2026. Fines de semana y feriados nacionales fijos no tienen Punta. Cambiar una tarifa no recalcula las cargas ya guardadas.</p>`;
    const rank = L.rankNetworks(groups(), now, 30);
    h += `<h3>Cargadores públicos ahora · para 30 kWh</h3>`;
    h += rank.map((x, i) => `<div class="kv"><span>${x.network}<em>${x.variant.label}${x.variant.fee > 0 ? ` · + ${money(x.variant.fee)} fijo` : ''}</em></span><b>${money2(x.variant.price)}/kWh${i === 0 ? '<em>el más barato ahora</em>' : `<em>efectivo ${money2(x.effective)}</em>`}</b></div>`).join('');
    h += `<p class="note">Datos ${net.source}${net.at ? ' · ' + shortDate(new Date(net.at)) + ' ' + hhmm(new Date(net.at)) : ''}. Fuente no oficial: evuruguay.com. El efectivo reparte el cargo fijo entre los kWh.</p>`;
    $('#precios').innerHTML = h;
  }
  $('#precios').addEventListener('click', (e) => { const b = e.target.closest('[data-ps]'); if (b) { S.puntaStart = +b.dataset.ps; persist(); const y = $('#precios').scrollTop; renderAll(); $('#precios').scrollTop = y; } });
  $('#precios').addEventListener('change', (e) => {
    const k = { 'r-valle': 'valle', 'r-llano': 'llano', 'r-punta': 'punta' }[e.target.id], n = num(e.target.value);
    if (!k || !(n > 0)) return;
    S.rates[k] = n; persist();
  });

  /* ---------- Render general ---------- */
  function renderTop() {
    const p = period(new Date()), s = L.statsBetween(S.charges, p.from, p.end);
    $('#topBar').innerHTML = `<b style="font-weight:400">${money(s.total)}</b> <span>· ${gPeriod === 'mes' ? 'este mes' : '30 días'}</span>`;
  }
  function renderAll() {
    renderTop(); renderList(); renderGasto(); renderAuto(); renderPrecios();
    if (stack.includes('prog')) renderProg();
  }

  /* ---------- Arranque ---------- */
  function fit() {
    if (innerWidth < 600) { phone.style.transform = ''; return; }
    phone.style.transform = `scale(${Math.min(1, (innerHeight - 32) / 874)})`;
  }
  addEventListener('resize', fit);
  fit(); renderAll(); renderStatus(); renderDraft(); homeRail.paint(); loadNetworks();
  window.__carga = { S, L, openFn, closeFn };
})();
</script>
</body>
</html>

