.lrow + .lrow { border-top: 1px solid #1a1a1a; }
.lrow:active { background: #0d0d0d; }
.lrow b { display: block; font-size: 17px; font-weight: 500; }
.lrow em { display: block; margin-top: 3px; font-style: normal; font-size: 13px; line-height: 1.3; color: var(--ink-2); }
.lrow svg { flex: none; fill: none; stroke: var(--ink-2); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.lrow.danger b { color: #ff6b6b; }
.msg { margin-top: 14px; padding: 12px 14px; border-radius: 14px; background: #1c1c1e; font-size: 14px; line-height: 1.35; }
.msg.err { color: #ff8a80; }
.msg.ok { color: var(--accent); }
.ghost { display: block; margin: 8px auto 0; }
.fx-prev { display: grid; place-items: center; padding: 18px 0 4px; }
.fx-prev .chip { width: 126px; height: 126px; --k: 1; }
.fx-name { margin-top: 10px; text-align: center; font-size: 15px; color: var(--ink-2); }
.fx-pick { display: flex; justify-content: space-between; margin-top: 18px; }
.fx-pick button { position: relative; width: 44px; height: 44px; border-radius: 50%; transition: transform 140ms var(--ease-out); }
.fx-pick button:active { transform: scale(0.94); }
.fx-pick button[aria-pressed="true"]::after { content: ""; position: absolute; inset: -3px; border-radius: 50%; box-shadow: 0 0 0 2px var(--ink); }
.fx-pick .chip { --k: 1; }
.fx-sw { display: flex; justify-content: space-between; }
.fx-sw button { position: relative; width: 44px; height: 44px; display: grid; place-items: center; }
.fx-sw button i { display: block; width: 28px; height: 28px; border-radius: 50%; transition: transform 140ms var(--ease-out); }
.fx-sw button:active i { transform: scale(0.92); }
.fx-sw button[aria-pressed="true"] i { box-shadow: 0 0 0 2px var(--bg), 0 0 0 4px var(--ink); }
.fx-sec { margin: 22px 0 0; }
.fx-sec h3 { margin: 0 0 8px; }
.fx-sec .seg.wide { margin-top: 0; }

