/* ---------- Fichas de póker: diseño de cada círculo del inicio ---------- */
const CHIP_COLORS = [['#4fb58a', 'Verde'], ['#4a8fe0', 'Azul'], ['#d65a52', 'Rojo'], ['#e08a3c', 'Naranja'], ['#8c6fd6', 'Violeta'], ['#d9648f', 'Rosa'], ['#3fb3c4', 'Turquesa'], ['#6b6b72', 'Grafito']];
const CHIP_EDGES = [['marcas', 'Marcas'], ['puntos', 'Puntos'], ['rayas', 'Rayas'], ['liso', 'Liso']];
const CHIP_WEIGHTS = { fino: 1.1, normal: 1.5, grueso: 2 };
const chipDefault = () => ({ color: CHIP_COLORS[0][0], edge: 'marcas', tone: 'claro', ring: true, weight: 'normal' });
/** Deja solo valores permitidos: sirve también para fichas que llegan de un respaldo. */
function cleanChip(c) {
  const d = chipDefault(); if (!c || typeof c !== 'object') return d;
  return { color: /^#[0-9a-f]{6}$/i.test(c.color) ? c.color : d.color, edge: CHIP_EDGES.some((e) => e[0] === c.edge) ? c.edge : d.edge,
    tone: c.tone === 'oscuro' ? 'oscuro' : 'claro', ring: c.ring !== false, weight: CHIP_WEIGHTS[c.weight] ? c.weight : d.weight };
}
const cleanChips = (all) => Object.fromEntries(Object.keys(ICONS).map((id) => [id, cleanChip(all && all[id])]));
S.chips = cleanChips(S.chips);
/**
 * La ficha entera es un SVG plano: cuerpo, marcas del borde (trazo discontinuo sobre una circunferencia), anillo y ícono.
 * Los colores usan --k (0 = ficha al costado, 1 = ficha en el centro): la del centro se ilumina, las demás quedan en gris.
 */
function chipSvg(id, c = S.chips[id]) {
  const E = { marcas: ['21 22.2', 12, 'butt', 10.5], puntos: ['0.01 21.59', 6, 'round', 0], rayas: ['3 11.4', 12, 'butt', 1.5] }[c.edge]; // 8, 16 y 24 marcas sobre r = 55
  return `<svg class="chip" viewBox="0 0 126 126" aria-hidden="true" style="--cc:${c.color};--ce:${c.tone === 'oscuro' ? '#1a1a1c' : '#fff'}"><circle class="body" cx="63" cy="63" r="63"/>`
    + (E ? `<circle class="mk" cx="63" cy="63" r="55" stroke-width="${E[1]}" stroke-dasharray="${E[0]}" stroke-dashoffset="${E[3]}" stroke-linecap="${E[2]}" transform="rotate(-90 63 63)"/>` : '')
    + `<circle class="rim" cx="63" cy="63" r="62"/>` + (c.ring ? '<circle class="ring" cx="63" cy="63" r="42"/>' : '')
    + `<g class="ic" transform="translate(36 36) scale(2.25)" stroke-width="${CHIP_WEIGHTS[c.weight]}">${ICONS[id]}</g></svg>`;
}
/** La ficha central de Registrar y Programar toma el color de su ficha del inicio. */
function paintGo() { [['cargar', '#fn-cargar'], ['prog', '#fn-prog']].forEach(([id, sel]) => $(sel).style.setProperty('--go', S.chips[id].color)); }
paintGo();

