    } else if (n) h += `<p class="note">${nCargas(m.added)} nuevas${m.duplicates ? `, ${m.duplicates} repetidas en el archivo se saltean` : ''}.${sampleCount() ? ' Los datos de ejemplo se quitan.' : ''}</p>`;
    h += `<button class="pill" data-imp="go">Importar${m.added ? ` ${nCargas(m.added)}` : ''}</button><button class="link ghost" data-imp="pick">Elegir otro archivo</button>`;
  }
  $('#importar').innerHTML = h;
}
function applyImport() {
  const { b, mode } = IMP; if (!b) return;
  const m = L.mergeCharges(S.charges, b.charges, mode);
  S.charges = m.charges;
  if (b.vehicle) S.vehicle = { ...S.vehicle, ...b.vehicle };
  if (b.rates) S.rates = { ...b.rates };
  if (b.puntaStart) S.puntaStart = b.puntaStart;
  if (b.charger) { S.amps = b.charger.amps; S.volts = b.charger.volts; }
  if (b.chips) { S.chips = cleanChips(b.chips); homeRail.refresh(); paintGo(); }
  persist(); IMP = { b: null, mode: 'merge', err: null };
  while (stack.length) closeFn();
  renderAll();
  flash(m.added ? `${nCargas(m.added)} ${m.added === 1 ? 'importada' : 'importadas'}` : 'Respaldo importado');
}
$('#impFile').addEventListener('change', async (e) => {
  const f = e.target.files[0]; e.target.value = ''; if (!f) return;
  try { IMP = { b: L.parseBackup(JSON.parse(await f.text())), mode: 'merge', err: null }; }
  catch (err) { IMP = { b: null, mode: 'merge', err: err instanceof SyntaxError ? 'No se pudo leer ese archivo: no es un respaldo.' : err.message }; }
  renderImport();
});
$('#importar').addEventListener('click', (e) => {
  const a = e.target.closest('[data-imp]'); if (!a) return;
  if (a.dataset.imp === 'pick') $('#impFile').click();
  else if (a.dataset.imp === 'mode') { IMP.mode = a.dataset.v; renderImport(); }
  else if (a.dataset.imp === 'go') applyImport();
});

/* ----- Taller de fichas ----- */
let fxSel = 'cargar';
const fxSeg = (k, items, sel) => `<div class="seg wide" role="group">${items.map(([v, l]) => `<button data-fx="${k}" data-v="${v}" aria-pressed="${String(sel) === v}">${l}</button>`).join('')}</div>`;
function renderFichas() {
  const c = S.chips[fxSel], y = $('#fichas').scrollTop;
  let h = `<div class="fx-prev">${chipSvg(fxSel)}</div><p class="fx-name">${FUNCS.find((f) => f.id === fxSel).name}</p>`;
  h += `<div class="fx-pick" role="group" aria-label="Elegir ficha">${FUNCS.map((f) => `<button data-fx="sel" data-v="${f.id}" aria-label="${f.name}" aria-pressed="${f.id === fxSel}">${chipSvg(f.id)}</button>`).join('')}</div>`;
  h += `<div class="fx-sec"><h3>Color</h3><div class="fx-sw" role="group" aria-label="Color">${CHIP_COLORS.map(([hex, n]) => `<button data-fx="color" data-v="${hex}" aria-label="${n}" aria-pressed="${hex === c.color}"><i style="background:${hex}"></i></button>`).join('')}</div></div>`;
  h += `<div class="fx-sec"><h3>Borde</h3>${fxSeg('edge', CHIP_EDGES, c.edge)}</div>`;
  h += `<div class="fx-sec"><h3>Tono del borde</h3>${fxSeg('tone', [['claro', 'Claro'], ['oscuro', 'Oscuro']], c.tone)}</div>`;
  h += `<div class="fx-sec"><h3>Anillo interior</h3>${fxSeg('ring', [['1', 'Con anillo'], ['0', 'Sin anillo']], c.ring ? '1' : '0')}</div>`;
  h += `<div class="fx-sec"><h3>Trazo del ícono</h3>${fxSeg('weight', [['fino', 'Fino'], ['normal', 'Normal'], ['grueso', 'Grueso']], c.weight)}</div>`;
  h += '<button class="pill" data-fx="all">Usar este diseño en todas</button><button class="link ghost" data-fx="reset">Restablecer esta ficha</button>';
  $('#fichas').innerHTML = h; $('#fichas').scrollTop = y;
}
$('#fichas').addEventListener('click', (e) => {
  const b = e.target.closest('[data-fx]'); if (!b) return;
  const k = b.dataset.fx, v = b.dataset.v, c = S.chips[fxSel];
  if (k === 'sel') fxSel = v;
  else if (k === 'all') FUNCS.forEach((f) => (S.chips[f.id] = { ...c }));
  else if (k === 'reset') S.chips[fxSel] = chipDefault();
  else if (k in c) c[k] = k === 'ring' ? v === '1' : v;
  persist(); homeRail.refresh(); paintGo(); renderFichas();
});

/* ---------- Render general ---------- */
function renderTop() {

  if (id === 'cargar') renderCargar();
  if (id === 'importar') { IMP = { b: null, mode: 'merge', err: null }; renderImport(); }
  if (id === 'fichas') renderFichas();
}

